// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"dabigatran":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es das zentrale Gerinnungsenzym Thrombin direkt blockiert. Eingenommen wird die unwirksame Vorstufe Dabigatranetexilat (Prodrug), die im Körper durch Esterasen rasch in Dabigatran umgewandelt wird. Dabigatran hemmt freies und an Gerinnsel gebundenes Thrombin reversibel und verhindert so die Bildung von Fibrin und die thrombinbedingte Aktivierung der Blutplättchen. Es wird zu rund 80 % unverändert über die Nieren ausgeschieden; als spezifisches Gegenmittel steht Idarucizumab zur Verfügung.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Nasenbluten","Magen-Darm-Blutungen","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Übelkeit","Hautblutungen","Blutungen der Harn- und Geschlechtsorgane, Blut im Urin"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeit, Hautausschlag, Juckreiz","Blutergüsse (Hämatome), Bluthusten","Magen-Darm-Geschwüre, Entzündung der Speiseröhre, Reflux, Schluckbeschwerden, Erbrechen","Blutungen aus Enddarm und Hämorrhoiden","Leberfunktionsstörung, erhöhte Leberwerte"],"selten":["Anaphylaktische Reaktion, Angioödem, Nesselsucht","Gelenkblutungen","Blutungen an Einstich-, Katheter- und Wundstellen"],"unbekannt":["Agranulozytose, Neutropenie (Mangel an weissen Blutkörperchen)","Bronchospasmus","Haarausfall"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich. Frauen im gebärfähigen Alter sollen während der Behandlung eine Schwangerschaft vermeiden.","stillzeit":"Keine Daten beim Menschen – während der Behandlung nicht stillen.","hinweise":["Kapseln ganz mit Wasser schlucken, nicht öffnen oder zerkauen – der Inhalt wird sonst viel stärker aufgenommen (Blutungsgefahr).","Kapseln in der Originalverpackung (Blister) lassen und vor Feuchtigkeit schützen.","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen, bei älteren Menschen mindestens jährlich.","Nicht eigenmächtig absetzen; vor Operationen, Zahnbehandlungen und neuen Medikamenten Arzt oder Apotheke informieren."],"darreichung":["Hartkapseln"]},"dabrafenib":{"wirkmechanismus":"Hemmt ein krankhaft dauerhaft eingeschaltetes Wachstumssignal in Tumorzellen mit BRAF-Mutation. Dabrafenib blockiert die mutierte BRAF-Kinase (V600E, V600K, V600D) und damit den MAPK-Signalweg (RAF-MEK-ERK). Zusammen mit dem MEK-Hemmer Trametinib wird der Signalweg an zwei Stellen gehemmt; das verstärkt die Wirkung, verzögert Resistenzen und vermindert neue Hauttumoren, die durch eine paradoxe Aktivierung des Signalwegs in gesunden Zellen entstehen können.","nebenwirkungen":{"sehrHaeufig":["Fieber, Schüttelfrost, Müdigkeit (vor allem mit Trametinib)","Kopfschmerzen","Übelkeit, Erbrechen, Durchfall, Appetitlosigkeit","Hautpapillome, Hyperkeratose (Hautverhornung), Hautausschlag, trockene Haut, Haarausfall, Hand-Fuss-Syndrom","Gelenk- und Muskelschmerzen","Husten","Bluthochdruck und Blutungen (mit Trametinib)"],"haeufig":["Plattenepithelkarzinom der Haut, Basalzellkarzinom","Lichtempfindlichkeit (Photosensibilität)","Erhöhter Blutzucker, tiefes Phosphat oder Natrium im Blut","Verminderte Herzpumpfunktion (mit Trametinib)","Neutropenie (mit Trametinib)","Erhöhte Leberwerte","Pannikulitis (Entzündung des Unterhautfettgewebes)"],"gelegentlich":["Neues Melanom","Uveitis (Entzündung im Auge)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Nierenversagen, Nierenentzündung (Nephritis)","Überempfindlichkeitsreaktionen"],"unbekannt":["Hämophagozytische Lymphohistiozytose (HLH; lebensbedrohliche Überaktivierung des Immunsystems)","Schwere Hautreaktionen (z. B. DRESS, Stevens-Johnson-Syndrom) mit Trametinib","Sarkoidose"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen zuverlässig nichthormonal verhüten – bei Dabrafenib allein bis 2 Wochen, mit Trametinib bis 16 Wochen nach Behandlungsende.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Kapseln zweimal täglich im Abstand von etwa 12 Stunden nüchtern einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit.","Bei Fieber ab 38 °C die Behandlung unterbrechen und sofort ärztlich melden.","Haut regelmässig kontrollieren lassen, neue Hautveränderungen melden und Sonnenschutz verwenden.","Sehstörungen, Blutungen oder Atemnot rasch ärztlich abklären."],"darreichung":["Hartkapseln","Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"dacarbazin":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen, indem es ihr Erbgut schädigt. Dacarbazin ist eine Vorstufe (Prodrug), die in der Leber vor allem über CYP1A1 und CYP1A2 zu MTIC umgewandelt wird. Daraus entsteht ein Methyldiazonium-Ion, das die DNA methyliert (v. a. am Guanin) und so die Zellteilung stört.","nebenwirkungen":{"haeufig":["Knochenmarkhemmung: Anämie, Leukopenie, Thrombozytopenie","Appetitlosigkeit, Übelkeit, Erbrechen"],"gelegentlich":["Infektionen","Grippeähnliche Beschwerden (Fieber, Muskelschmerzen, Unwohlsein)","Haarausfall, Dunkelfärbung der Haut","Lichtempfindlichkeit der Haut"],"selten":["Lebervenenverschluss mit Lebernekrose (teils tödlich), erhöhte Leberwerte","Panzytopenie, Agranulozytose","Anaphylaxie (schwere allergische Reaktion)","Nierenfunktionsstörungen","Durchfall","Kopfschmerzen, Sehstörungen, Verwirrtheit, Krampfanfälle","Gesichtsrötung und Kribbeln im Gesicht","Hautrötung, Nesselsucht, Reizung an der Injektionsstelle"]},"schwangerschaft":"Kontraindiziert. Frauen und Männer müssen während und bis 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Infusion vor Licht geschützt; Austreten neben die Vene vermeiden.","Haut vor Sonne schützen (erhöhte Lichtempfindlichkeit).","Bei Bauchschmerzen, Gelbfärbung der Haut oder Fieber sofort ärztliche Hilfe holen.","Gegen Übelkeit werden vorbeugend Mittel gegen Erbrechen gegeben."],"darreichung":["Pulver zur Herstellung einer Injektions- bzw. Infusionslösung"]},"dacomitinib":{"wirkmechanismus":"Blockiert dauerhaft die Wachstumssignal-Enzyme der HER-Familie auf Krebszellen. Dacomitinib bindet kovalent und irreversibel an EGFR (HER1), HER2 und HER4 und hemmt deren Tyrosinkinase-Aktivität. Bei Tumoren mit Exon-19-Deletion oder L858R-Mutation wird so das Wachstum gebremst.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Hautausschlag (akneähnlich), trockene Haut, Juckreiz","Paronychie (Nagelbettentzündung)","Stomatitis (Mundschleimhautentzündung)","Appetitlosigkeit, Gewichtsverlust","Bindehautentzündung","Haarausfall","Erhöhte Leberwerte"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis (Lungenentzündung ohne Erreger)","Keratitis (Hornhautentzündung)","Flüssigkeitsmangel (Dehydratation)","Geschmacksstörung","Hand-Fuss-Syndrom, Hautrisse, vermehrte Behaarung","Müdigkeit, Schwäche"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig. Frauen im gebärfähigen Alter müssen während und mindestens 17 Tage nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit, unabhängig von den Mahlzeiten einnehmen.","Säureblocker (PPI) vermeiden; bei jeder neuen Medikation auf die starke CYP2D6-Hemmung hinweisen.","Bei Durchfall früh Loperamid einnehmen und viel trinken; Haut pflegen und vor Sonne schützen.","Plötzliche Atemnot, Husten oder Fieber ärztlich abklären."],"darreichung":["Filmtabletten"]},"dalbavancin":{"wirkmechanismus":"Tötet grampositive Bakterien ab, indem es den Aufbau ihrer Zellwand blockiert. Dalbavancin bindet wie andere Glykopeptide an die D-Alanyl-D-Alanin-Enden der Zellwand-Bausteine und verhindert deren Quervernetzung. Eine fettlösliche Seitenkette verankert es zusätzlich in der Bakterienmembran und verstärkt die Wirkung. Wegen seiner sehr langen Halbwertszeit (mehr als eine Woche) reicht eine Einzeldosis oder zwei Dosen im Abstand von einer Woche.","nebenwirkungen":{"haeufig":["Übelkeit","Durchfall","Kopfschmerzen"],"gelegentlich":["Pilzinfektionen (Mund, Scheide), Harnwegsinfekte","Blutbildveränderungen (Anämie, Leukopenie, Neutropenie, Eosinophilie)","Schwindel, Geschmacksstörungen, Schlaflosigkeit","Hitzegefühl (Flush), Venenentzündung","Erbrechen, Verstopfung, Bauchschmerzen","Juckreiz, Nesselsucht, Hautausschlag","Erhöhte Leberwerte","Reaktionen bei der Infusion"],"selten":["Anaphylaktoide Reaktionen (schwere allergieähnliche Reaktionen)","Bronchospasmus (Verkrampfung der Atemwege)","Thrombozytopenie (Mangel an Blutplättchen)"],"unbekannt":["Clostridioides-difficile-Kolitis (schwere Darmentzündung)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; im Tierversuch verzögerte Entwicklung der Föten. Nur anwenden, wenn unbedingt erforderlich.","stillzeit":"Nicht bekannt, ob Dalbavancin beim Menschen in die Muttermilch übergeht (bei Ratten ja). Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird als Infusion über 30 Minuten gegeben; meist genügt eine einzige Gabe, teilweise folgt eine zweite nach einer Woche.","Wegen der langen Wirkdauer können Nebenwirkungen noch Wochen nach der Infusion auftreten – starken Durchfall oder Hautausschlag melden."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"dalteparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Dalteparin ist ein aus Heparin gewonnenes niedermolekulares Heparin: Es verstärkt die Wirkung des körpereigenen Hemmstoffs Antithrombin, der vor allem den Gerinnungsfaktor Xa und in geringerem Mass Thrombin (Faktor IIa) blockiert. Im Vergleich zu unfraktioniertem Heparin wirkt es gleichmässiger und länger, sodass ein bis zwei Spritzen unter die Haut pro Tag genügen. Die Wirkung lässt sich über die Anti-Xa-Aktivität messen; die Ausscheidung erfolgt überwiegend über die Nieren.","nebenwirkungen":{"haeufig":["Blutungen","Bluterguss (Hämatom) und Schmerzen an der Einstichstelle","Leichte, meist vorübergehende Abnahme der Blutplättchen (Thrombozytopenie Typ I)","Vorübergehender Anstieg der Leberwerte (Transaminasen)"],"gelegentlich":["Überempfindlichkeitsreaktionen"],"selten":["Hautnekrosen (absterbende Haut) an der Einstichstelle","Vorübergehender Haarausfall"],"unbekannt":["Heparininduzierte Thrombozytopenie Typ II (HIT; immunbedingt, mit oder ohne Thrombosen)","Anaphylaktische Reaktionen","Hirnblutungen und Blutungen im hinteren Bauchraum (retroperitoneal), teils tödlich","Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie mit möglicher Lähmung","Hautausschlag"]},"schwangerschaft":"Dalteparin passiert die Plazenta nicht; bisherige Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko. Anwendung nach ärztlicher Abwägung möglich; eine rückenmarksnahe Anästhesie bei der Geburt muss zeitlich abgestimmt werden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über und wird vom Säugling über den Darm kaum aufgenommen; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Unter die Haut spritzen (meist am Bauch), nie in den Muskel; Einstichstelle wechseln und nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen","Injektionslösung in Ampullen"]},"danicopan":{"wirkmechanismus":"Ergänzt die Wirkung eines C5-Hemmers, indem es den Abbau markierter roter Blutkörperchen in Leber und Milz bremst. Danicopan ist ein oral wirksamer Hemmer von Faktor D, einer Protease, die für die Aktivierung des alternativen Komplementwegs unerlässlich ist. Dadurch werden weniger C3-Fragmente auf den roten Blutkörperchen abgelagert und die extravaskuläre Hämolyse nimmt ab. Der C5-Hemmer verhindert weiterhin den Blutzerfall in den Gefässen.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Erbrechen, Übelkeit","Durchfall","Fieber","Erhöhte Leberwerte"],"unbekannt":["Schwere Infektionen mit bekapselten Bakterien (Meningokokken, Pneumokokken)"]},"schwangerschaft":"Nicht empfohlen; Erfahrungen fehlen. Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Dreimal täglich mit einer Mahlzeit einnehmen; die Behandlung mit dem C5-Hemmer unverändert weiterführen.","Patientenkarte mitführen. Bei Fieber, starken Kopfschmerzen, Nackensteifigkeit oder Hautflecken sofort den Notfall aufsuchen.","Leberwerte vor Beginn und während der Behandlung kontrollieren lassen."],"darreichung":["Filmtabletten"]},"dantrolen":{"wirkmechanismus":"Entspannt die Skelettmuskulatur direkt im Muskel. Dantrolen hemmt am Ryanodin-Rezeptor (RyR1) die Freisetzung von Calcium aus dem sarkoplasmatischen Retikulum und entkoppelt so Erregung und Kontraktion der Muskelfaser. Bei der malignen Hyperthermie unterbricht es dadurch den unkontrollierten Calcium-Ausstrom, der Muskelstarre, Fieber und Stoffwechselentgleisung verursacht. Die Signalübertragung vom Nerv auf den Muskel wird nicht beeinflusst.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Müdigkeit, allgemeines Unwohlsein","Schwindel","Muskelschwäche","Durchfall (teils stark)","Übelkeit, Erbrechen, Appetitlosigkeit","Kopfschmerzen","Hautausschlag"],"unbekannt":["Leberentzündung (Hepatitis) und Gelbsucht, in Einzelfällen tödliches Leberversagen","Krampfanfälle","Pleuraerguss (Flüssigkeit im Brustfell)","Atemdepression","Sehstörungen","Venenentzündung an der Infusionsstelle"]},"schwangerschaft":"Kapseln in der Schwangerschaft nicht anwenden. Bei maligner Hyperthermie hat die lebensrettende Behandlung mit der Infusion Vorrang.","stillzeit":"Dantrolen geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Leberwerte vor Beginn und regelmässig während der Behandlung mit Kapseln kontrollieren; bei Gelbfärbung, dunklem Urin oder Oberbauchschmerzen sofort ärztlich melden.","Kann Müdigkeit und Muskelschwäche verursachen: Vorsicht beim Autofahren, keinen Alkohol trinken.","Zeigt sich nach einigen Wochen keine Besserung der Spastik, wird die Behandlung beendet (Leberrisiko)."],"darreichung":["Kapseln","Pulver zur Herstellung einer Infusionslösung"]},"dapagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren überschüssigen Zucker mit dem Urin ausscheiden. Dapagliflozin hemmt selektiv und reversibel den Natrium-Glukose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus, der normalerweise den grössten Teil der gefilterten Glukose in den Körper zurückholt. Die Wirkung ist unabhängig vom Insulin; zusätzlich entstehen eine leichte osmotische Diurese, eine vermehrte Natriumausscheidung, ein Kalorienverlust und eine mässige Blutdrucksenkung. Bei Herz- und Nierenkrankheit tragen vermutlich die Senkung des Drucks in den Nierenkörperchen (tubuloglomerulärer Feedback) und die Entlastung des Herzens zur Schutzwirkung bei.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Genitalinfektionen wie Scheidenpilz (Vulvovaginitis) oder Eichelentzündung (Balanitis)","Harnwegsinfekte","Vermehrtes Wasserlassen (Polyurie), Brennen beim Wasserlassen (Dysurie)","Schwindel","Hautausschlag","Rückenschmerzen","Anstieg von Hämatokrit und Blutfetten, vorübergehender Rückgang der Nierenfunktion zu Therapiebeginn"],"gelegentlich":["Volumenmangel (Austrocknung, tiefer Blutdruck)","Durst, Mundtrockenheit","Verstopfung","Nächtliches Wasserlassen (Nykturie)","Juckreiz im Genitalbereich","Gewichtsabnahme","Anstieg von Kreatinin und Harnstoff im Blut"],"selten":["Diabetische Ketoazidose (lebensbedrohliche Übersäuerung, auch bei fast normalem Blutzucker)"],"sehrSelten":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Tubulointerstitielle Nephritis (Nierenentzündung)"]},"schwangerschaft":"Nicht empfohlen, besonders im 2. und 3. Schwangerschaftsdrittel (Nierenschäden im Tierversuch). Bei Eintritt einer Schwangerschaft absetzen und ärztlich auf eine andere Behandlung umstellen.","stillzeit":"Nicht anwenden, da ein Übergang in die Muttermilch und Auswirkungen auf das gestillte Kind nicht ausgeschlossen werden können.","hinweise":["Der Urin-Zuckertest fällt unter der Behandlung immer positiv aus – zur Kontrolle den Blutzucker messen.","Bei akuten Erkrankungen mit Erbrechen, Durchfall oder wenig Trinken sowie vor grösseren Operationen nach ärztlicher Anweisung pausieren (Ketoazidose- und Austrocknungsgefahr).","Warnzeichen einer Ketoazidose (Übelkeit, Erbrechen, Bauchschmerzen, starker Durst, rasche Atmung, Verwirrtheit, ungewöhnliche Müdigkeit) sofort ärztlich abklären lassen.","Ausreichend trinken und auf Intimhygiene achten; Einnahme einmal täglich, unabhängig von den Mahlzeiten."],"darreichung":["Filmtabletten","Retardtabletten (Kombination mit Metformin)"]},"dapoxetin":{"wirkmechanismus":"Verzögert den Samenerguss. Dapoxetin hemmt die Wiederaufnahme von Serotonin in die Nervenzellen und verstärkt so die Serotoninwirkung im Gehirn, die den Ejakulationsreflex zentral bremst. Es wird rasch aufgenommen und rasch ausgeschieden; deshalb wird es nur bei Bedarf 1–3 Stunden vor dem Geschlechtsverkehr eingenommen.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Kopfschmerzen","Übelkeit"],"haeufig":["Angst, Unruhe, Schlafstörungen","Schläfrigkeit, Konzentrationsstörungen, Zittern","Verschwommenes Sehen","Durchfall, Erbrechen, Verstopfung, Bauchschmerzen","Mundtrockenheit","Vermehrtes Schwitzen","Erektionsstörung, verminderte Libido","Müdigkeit, Reizbarkeit"],"gelegentlich":["Synkope (Ohnmacht), auch mit Sturzverletzungen","Blutdruckabfall, Schwindel beim Aufstehen","Verlangsamter Herzschlag, kurze Herzpausen (Sinusarrest), Herzrasen","Depressive Verstimmung, Verwirrtheit","Pupillenerweiterung, Sehstörungen","Ejakulations- und Orgasmusstörungen"],"selten":["Plötzliches Einschlafen","Schwindel bei körperlicher Anstrengung","Plötzlicher Stuhldrang"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["1–3 Stunden vor dem Geschlechtsverkehr mit mindestens einem vollen Glas Wasser einnehmen, höchstens einmal in 24 Stunden.","Bei Vorzeichen einer Ohnmacht (Schwindel, Benommenheit, Schwitzen) sofort hinlegen; nicht Auto fahren, wenn solche Beschwerden auftreten.","Keinen Alkohol und keine Drogen dazu einnehmen.","Nach 4 Wochen bzw. mindestens 6 Einnahmen den Nutzen ärztlich beurteilen lassen."],"darreichung":["Filmtabletten"]},"daptomycin":{"wirkmechanismus":"Durchlöchert die Hülle von Bakterien und tötet sie rasch ab. Daptomycin lagert sich calciumabhängig in die Zellmembran grampositiver Bakterien ein, führt zu einer raschen Depolarisation und stoppt die Synthese von DNA, RNA und Eiweissen. Es wirkt auch gegen Methicillin-resistente Staphylokokken (MRSA) und Vancomycin-resistente Enterokokken. In der Lunge wird es durch das Surfactant inaktiviert und ist deshalb gegen Lungenentzündungen unwirksam.","nebenwirkungen":{"haeufig":["Pilzinfektionen, Harnwegsinfektionen","Anämie (Blutarmut)","Angst, Schlaflosigkeit","Schwindel, Kopfschmerzen","Bluthochdruck oder tiefer Blutdruck","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verstopfung, Blähungen","Erhöhte Leberwerte und erhöhte Kreatinkinase (CK)","Ausschlag, Juckreiz, Gliederschmerzen, Reaktionen an der Infusionsstelle, Fieber"],"gelegentlich":["Eosinophilie, Thrombozythämie, erhöhte INR","Appetitlosigkeit, Hyperglykämie, Elektrolytstörungen","Kribbeln, Geschmacksstörungen, Zittern","Herzrhythmusstörungen (supraventrikuläre Tachykardie, Extrasystolen)","Myositis, Muskelschwäche, Muskel- und Gelenkschmerzen","Nierenfunktionsstörung bis Nierenversagen","Nesselsucht"],"selten":["Gelbsucht (Ikterus)","Verlängerte Prothrombinzeit"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Eosinophile Pneumonie, organisierende Pneumonie","Anaphylaxie, Angioödem, DRESS (schwere Arzneimittelreaktion)","Schwere bullöse Hautreaktionen, akute generalisierte exanthematische Pustulose (AGEP)","Periphere Neuropathie","Clostridioides-difficile-assoziierte Durchfälle","Tubulointerstitielle Nephritis"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung in der Stillzeit nur nach ärztlicher Abwägung, Stillen allenfalls unterbrechen.","hinweise":["Wird im Spital oder ambulant als Infusion bzw. Injektion einmal täglich verabreicht.","Muskelschmerzen, Muskelschwäche, Kribbeln oder Taubheit sowie neue Atemnot mit Fieber sofort melden.","Kreatinkinase (CK) wird mindestens wöchentlich kontrolliert, bei Risikopatienten häufiger."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"daratumumab":{"wirkmechanismus":"Markiert Myelomzellen, damit das Immunsystem sie zerstört. Daratumumab ist ein humaner monoklonaler IgG1-Antikörper gegen CD38, ein Eiweiss, das auf Myelom- und Plasmazellen in grosser Menge vorkommt. Er tötet die Tumorzellen über das Komplementsystem, über Immunzellen (antikörperabhängige Zytotoxizität und Phagozytose) und durch Auslösen des programmierten Zelltods; zudem vermindert er immunhemmende Zellen, die CD38 tragen. Weil auch rote Blutkörperchen etwas CD38 tragen, stört der Antikörper die Verträglichkeitstests vor Bluttransfusionen.","nebenwirkungen":{"sehrHaeufig":["Infektionen: Lungenentzündung, Bronchitis, obere Atemwege","Neutropenie, Thrombozytopenie, Anämie, Lymphopenie","Infusionsreaktionen (Husten, Atemnot, Schüttelfrost, verstopfte Nase, Übelkeit)","Periphere sensorische Neuropathie, Kopfschmerzen","Durchfall, Verstopfung, Übelkeit, Erbrechen","Müdigkeit, Fieber, periphere Ödeme, Schwäche","Rückenschmerzen, Muskelkrämpfe","Bluthochdruck"],"haeufig":["Sepsis, Harnwegsinfekte, Grippe, Zytomegalievirus-Infektion","Vorhofflimmern","Lungenödem","Hyperglykämie, Hypokalzämie, Austrocknung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hautausschlag, Juckreiz","Synkope (Ohnmacht)","Reaktionen an der Injektionsstelle (subkutane Form)"],"gelegentlich":["Hepatitis-B-Reaktivierung"],"selten":["Anaphylaktische Reaktion"]},"schwangerschaft":"Nur bei zwingender Indikation (der Antikörper kann beim Kind Blutzellen vermindern). Frauen müssen während und bis 3 Monate nach der Behandlung sicher verhüten.","stillzeit":"Unbekannt, ob der Antikörper in die Muttermilch übergeht; nach ärztlicher Abwägung zwischen Stillen und Behandlung entscheiden.","hinweise":["Vor Beginn werden Blutgruppe und Antikörpersuchtest bestimmt; bei jeder Bluttransfusion – bis 6 Monate nach der letzten Gabe – auf die Behandlung hinweisen (Patientenausweis).","Vor jeder Gabe Vorbehandlung mit Kortikosteroid, Antihistaminikum und Paracetamol; Reaktionen sind auch Stunden später möglich.","Fieber oder Infektzeichen sofort melden; vor Beginn Test auf Hepatitis B."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung zur subkutanen Anwendung"]},"darbepoetin-alfa":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden. Darbepoetin alfa wirkt wie das körpereigene Hormon Erythropoetin am Erythropoetin-Rezeptor der Vorläuferzellen im Knochenmark. Durch zwei zusätzliche Zuckerketten im Molekül wird es langsamer abgebaut und hat eine etwa dreimal längere Halbwertszeit als Epoetin alfa. Deshalb genügen Spritzen in Abständen von einer bis vier Wochen; ausreichend Eisen ist Voraussetzung für die Wirkung.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck (bei Nierenkranken)","Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Nesselsucht)","Wassereinlagerungen (Ödeme, bei Krebspatienten)"],"haeufig":["Schlaganfall (bei Nierenkranken)","Thrombosen und Embolien, inkl. Lungenembolie (bei Krebspatienten)","Hautrötung (Erythem)","Schmerzen an der Injektionsstelle"],"gelegentlich":["Krampfanfälle","Thrombose des Dialyse-Shunts"],"unbekannt":["Erythroblastopenie (PRCA) durch Antikörper gegen Erythropoetin","Hypertensive Krise mit Hirnfunktionsstörung (Enzephalopathie)","Anaphylaxie, Angioödem (Schwellung von Gesicht und Rachen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; Erfahrungen beim Menschen fehlen weitgehend.","stillzeit":"Nicht bekannt, ob Darbepoetin in die Muttermilch übergeht; Anwendung nur nach Abwägung.","hinweise":["Blutdruck regelmässig messen; bei starken Kopfschmerzen, Verwirrtheit oder Sehstörungen sofort ärztliche Hilfe holen.","Hämoglobin und Eisenwerte werden regelmässig kontrolliert; meist ist zusätzlich Eisen nötig.","Im Kühlschrank (2–8 °C) lagern, nicht einfrieren oder schütteln.","Missbrauch als Dopingmittel ist verboten und gefährlich (Thrombosen, Herzinfarkt)."],"darreichung":["Injektionslösung in Fertigspritzen und Fertigpens (Spritze unter die Haut oder in die Vene)"]},"daridorexant":{"wirkmechanismus":"Fördert den Schlaf, indem es das Wachsignal des Gehirns dämpft, statt das Gehirn allgemein zu betäuben. Daridorexant blockiert beide Orexin-Rezeptoren (OX1R und OX2R) und verhindert so, dass die wachheitsfördernden Botenstoffe Orexin A und B andocken. Die Halbwertszeit beträgt etwa 8 Stunden; der Abbau erfolgt überwiegend über CYP3A4.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit (auch am Folgetag), Müdigkeit","Schwindel","Übelkeit"],"gelegentlich":["Schlaflähmung (vorübergehende Unfähigkeit, sich beim Einschlafen oder Aufwachen zu bewegen)","Halluzinationen beim Einschlafen oder Aufwachen"]},"schwangerschaft":"Kaum Erfahrungen; nur anwenden, wenn der Zustand der Frau es zwingend erfordert.","stillzeit":"Nicht bekannt, ob Daridorexant in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – nur nach ärztlicher Abwägung, das Kind auf Schläfrigkeit beobachten.","hinweise":["Abends etwa 30 Minuten vor dem Zubettgehen einnehmen; eine Einnahme kurz nach einer Mahlzeit kann den Wirkungseintritt verzögern.","Keinen Alkohol trinken; Grapefruitsaft meiden.","Am Folgetag kann die Fahrtüchtigkeit beeinträchtigt sein – kein Fahrzeug lenken, wenn man sich nicht vollständig wach fühlt.","Die Notwendigkeit der Behandlung innerhalb von 3 Monaten ärztlich überprüfen lassen."],"darreichung":["Filmtabletten"]},"darifenacin":{"wirkmechanismus":"Entspannt die Blasenmuskulatur und vermindert so Harndrang und häufiges Wasserlassen. Darifenacin blockiert selektiv den Muskarin-M3-Rezeptor, über den der Blasenmuskel (Detrusor) zur Kontraktion angeregt wird. Dadurch nimmt die Blasenkapazität zu, und unwillkürliche Blasenkontraktionen werden gedämpft. Wegen der M3-Selektivität sind Wirkungen an Herz und Gehirn geringer, aber nicht ausgeschlossen.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Obstipation (Verstopfung)"],"haeufig":["Kopfschmerzen","Trockene Augen","Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Bauchschmerzen","Trockene Nasenschleimhaut"],"gelegentlich":["Harnverhalt","Harnwegsinfekt","Schwindel, Schläfrigkeit","Verschwommenes Sehen","Geschmacksstörung","Bluthochdruck","Hautausschlag, Juckreiz","Erhöhte Leberwerte"],"unbekannt":["Verwirrtheit","Halluzinationen","Depressive Verstimmung, Stimmungsschwankungen","Angioödem (Schwellung von Gesicht und Rachen)"]},"schwangerschaft":"Nicht empfohlen, da nur begrenzte Daten vorliegen.","stillzeit":"Nur nach ärztlicher Abwägung; bei Tieren geht Darifenacin in die Milch über.","hinweise":["Retardtabletten unzerkaut mit Flüssigkeit schlucken, unabhängig von den Mahlzeiten.","Schwindel und verschwommenes Sehen sind möglich – Vorsicht beim Autofahren.","Bei anhaltender Verstopfung oder Schwierigkeiten beim Wasserlassen ärztlich abklären."],"darreichung":["Retardtabletten"]},"darolutamid":{"wirkmechanismus":"Blockiert die Wirkung männlicher Hormone auf Prostatakrebszellen. Darolutamid und sein aktiver Metabolit Keto-Darolutamid binden mit hoher Affinität an den Androgenrezeptor und hemmen kompetitiv die Bindung der Androgene, die Wanderung des Rezeptors in den Zellkern und das Ablesen androgenabhängiger Gene. Im Tierversuch gelangt Darolutamid kaum ins Gehirn, was das geringe Risiko für zentralnervöse Nebenwirkungen wie Krampfanfälle erklären könnte.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck","Hautausschlag","Verminderte Neutrophile (weisse Blutkörperchen)","Erhöhte Leberwerte (AST, ALT) und erhöhtes Bilirubin"],"haeufig":["Ischämische Herzkrankheit (Durchblutungsstörung des Herzens)","Herzinsuffizienz","Knochenbrüche","Schmerzen in Armen und Beinen, Muskel- und Knochenschmerzen","Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Arzneimittelbedingte Leberschädigung (Hepatitis)"]},"schwangerschaft":"Kontraindiziert bei Frauen, die schwanger sind oder werden könnten. Männer mit Partnerin im gebärfähigen Alter müssen während und bis 1 Woche nach der letzten Dosis wirksam verhüten.","stillzeit":"Nicht zutreffend – nicht zur Anwendung bei Frauen bestimmt.","hinweise":["Zweimal täglich mit einer Mahlzeit einnehmen, Tabletten ganz schlucken.","Die Hormonentzugstherapie (GnRH-Analogon) wird weitergeführt, sofern keine Orchiektomie erfolgt ist.","Bei Einnahme von Statinen die Ärztin oder den Arzt informieren und Muskelschmerzen melden.","Blutdruck und Leberwerte regelmässig kontrollieren."],"darreichung":["Filmtabletten"]},"darunavir":{"wirkmechanismus":"Verhindert, dass neu gebildete HI-Viren reifen und weitere Zellen infizieren. Darunavir hemmt die HIV-1-Protease, ein Enzym, das die viralen Gag-Pol-Vorläuferproteine in funktionsfähige Einzelproteine zerschneidet; es entstehen nur unreife, nicht infektiöse Viruspartikel. Darunavir bindet sehr fest an das Enzym und wirkt auch bei vielen Resistenzen gegen ältere Proteasehemmer. Weil es rasch über CYP3A4 abgebaut wird, wird es immer mit einem «Booster» (Ritonavir oder Cobicistat) kombiniert, der diesen Abbau hemmt – das erklärt die zahlreichen Wechselwirkungen.","nebenwirkungen":{"sehrHaeufig":["Durchfall"],"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen, Blähungen, Verdauungsbeschwerden","Kopfschmerzen, Schwindel","Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Schlaflosigkeit","Hautausschlag, Juckreiz","Erhöhte Blutfette (Cholesterin, Triglyceride), Diabetes mellitus","Erhöhte Leberwerte (ALT) und Amylase","Müdigkeit, Schwäche"],"gelegentlich":["Hepatitis (Leberentzündung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Herzinfarkt, Angina pectoris, QT-Verlängerung","Angioödem, Nesselsucht","Thrombozytopenie, Neutropenie, Anämie","Depression, Angst, Desorientierung","Akutes Nierenversagen, Nierensteine","Osteonekrose, Muskelschmerzen, Gynäkomastie (Brustvergrösserung beim Mann)"],"selten":["Stevens-Johnson-Syndrom","DRESS (schwere Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Erythema multiforme","Krampfanfälle, Ohnmacht","Kristallnephropathie (Ablagerung von Darunavir-Kristallen in der Niere)"],"unbekannt":["Toxische epidermale Nekrolyse","Akute generalisierte exanthematische Pustulose (AGEP)"]},"schwangerschaft":"Darunavir mit Ritonavir kann in der Schwangerschaft angewendet werden, wenn der Nutzen das Risiko rechtfertigt. Darunavir mit Cobicistat wird wegen zu tiefer Spiegel in der Schwangerschaft nicht empfohlen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Immer zusammen mit Ritonavir oder Cobicistat und mit einer Mahlzeit einnehmen (bessere Aufnahme).","Vor jedem neuen Medikament – auch rezeptfreien und pflanzlichen wie Johanniskraut – mit Ärztin, Arzt oder Apotheke Rücksprache nehmen.","Täglich ohne Unterbrechung einnehmen, damit keine Resistenzen entstehen.","Bei schwerem Hautausschlag mit Fieber, Blasen oder Schleimhautbeteiligung sofort ärztlich melden."],"darreichung":["Filmtabletten"]},"darunavir-cobicistat":{"wirkmechanismus":"Verhindert, dass das HI-Virus reife, ansteckende Viruspartikel bilden kann. Darunavir hemmt die HIV-Protease sehr fest und verhindert die Spaltung der viralen Vorläufer-Eiweisse; es entstehen unreife, nicht infektiöse Viren. Cobicistat wirkt selbst nicht gegen das Virus, sondern hemmt stark das Abbauenzym CYP3A und erhöht so die Darunavir-Spiegel. Cobicistat hemmt zudem den Nieren-Transporter MATE1, wodurch das Kreatinin leicht ansteigt, ohne dass die Nierenfunktion tatsächlich abnimmt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall, Übelkeit","Hautausschlag"],"haeufig":["Erbrechen, Bauchschmerzen, Blähungen, aufgetriebener Bauch, Verdauungsbeschwerden","Erhöhte Blutfette, Diabetes mellitus, Appetitlosigkeit","Erhöhte Leber- und Bauchspeicheldrüsenenzyme","Juckreiz, Nesselsucht","Abnorme Träume","Muskelschmerzen, Müdigkeit","Überempfindlichkeitsreaktionen","Kreatininanstieg (durch Cobicistat)"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Hepatitis","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Immunrekonstitutionssyndrom","Osteonekrose","Gynäkomastie","Schwäche"],"selten":["Stevens-Johnson-Syndrom","DRESS (schwere Überempfindlichkeitsreaktion mit Organbeteiligung)"],"unbekannt":["Toxische epidermale Nekrolyse","Akute generalisierte exanthematische Pustulose (AGEP)","Kristallnephropathie (Nierenschädigung durch Darunavir-Kristalle)"]},"schwangerschaft":"Nicht in der Schwangerschaft beginnen: Die Spiegel von Darunavir und Cobicistat sind im 2. und 3. Drittel stark erniedrigt – bei Eintritt einer Schwangerschaft auf eine andere Therapie umstellen.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Sehr viele Wechselwirkungen: vor jedem neuen Medikament – auch Asthmasprays, Potenzmitteln, Pille und pflanzlichen Mitteln – Ärztin, Arzt oder Apotheke informieren.","Ein leichter Kreatininanstieg zu Beginn ist durch Cobicistat bedingt und bedeutet nicht automatisch eine Nierenschädigung."],"darreichung":["Filmtabletten"]},"darunavir-cobicistat-emtricitabin-tenofoviralafenamid":{"wirkmechanismus":"Vier Wirkstoffe hemmen die Vermehrung des HI-Virus. Darunavir blockiert die HIV-Protease, sodass nur unreife, nicht infektiöse Viren entstehen. Emtricitabin und Tenofovir (aus dem Prodrug Tenofoviralafenamid) hemmen die Reverse Transkriptase durch Kettenabbruch und wirken auch gegen Hepatitis B. Cobicistat wirkt nicht gegen das Virus, sondern hemmt stark das Abbauenzym CYP3A und erhöht so die Darunavir-Spiegel; es hemmt zudem den Nieren-Transporter MATE1 (leichter Kreatininanstieg ohne echte Abnahme der Nierenfunktion).","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall","Hautausschlag"],"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen, Blähungen, Verdauungsbeschwerden","Abnorme Träume, Schwindel","Diabetes mellitus, erhöhte Blutfette, Appetitlosigkeit","Erhöhte Leberwerte","Juckreiz, Nesselsucht","Muskelschmerzen, Schwäche, Müdigkeit","Überempfindlichkeitsreaktionen","Kreatininanstieg (durch Cobicistat)"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Hepatitis","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Immunrekonstitutionssyndrom","Osteonekrose","Gynäkomastie"],"selten":["Stevens-Johnson-Syndrom","DRESS (schwere Überempfindlichkeitsreaktion mit Organbeteiligung)"],"unbekannt":["Toxische epidermale Nekrolyse","Akute generalisierte exanthematische Pustulose (AGEP)","Kristallnephropathie (Nierenschädigung durch Darunavir-Kristalle)"]},"schwangerschaft":"Nicht in der Schwangerschaft beginnen: Die Spiegel von Darunavir und Cobicistat sind im 2. und 3. Drittel stark erniedrigt – bei Eintritt einer Schwangerschaft auf eine andere Therapie umstellen.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Sehr viele Wechselwirkungen: vor jedem neuen Medikament – auch Asthmasprays, Potenzmitteln, Pille und pflanzlichen Mitteln – Ärztin, Arzt oder Apotheke informieren.","Bei Hepatitis B nicht eigenmächtig absetzen (Gefahr eines schweren Hepatitis-Schubs); ein leichter Kreatininanstieg zu Beginn ist durch Cobicistat bedingt."],"darreichung":["Filmtabletten"]},"dasatinib":{"wirkmechanismus":"Blockiert gezielt das krankhafte Enzym, das die Leukämiezellen zum Wachsen antreibt. Dasatinib hemmt die Tyrosinkinase BCR-ABL, die durch das Philadelphia-Chromosom entsteht, sowie Kinasen der SRC-Familie, c-KIT, PDGF-Rezeptor-beta und EPHA2. Es bindet sowohl an die aktive als auch an die inaktive Form von BCR-ABL und wirkt daher gegen viele Imatinib-resistente Mutationen, nicht aber gegen die T315I-Mutation.","nebenwirkungen":{"sehrHaeufig":["Mangel an Blutplättchen, weissen und roten Blutkörperchen","Infektionen","Flüssigkeitseinlagerungen, Pleuraerguss (Wasser im Brustfell), Atemnot","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Kopfschmerzen","Blutungen","Hautausschlag","Müdigkeit, Fieber, Muskel- und Gelenkschmerzen"],"haeufig":["Herzschwäche, Herzbeutelerguss, Herzrhythmusstörungen, Herzklopfen","Lungenhochdruck (pulmonale Hypertonie), Lungenödem, Lungenentzündung","Bluthochdruck","Magen-Darm-Blutungen, Kolitis (Dickdarmentzündung)","Fieberhafte Neutropenie","Haarausfall, Juckreiz, Akne, trockene Haut"],"gelegentlich":["Herzinfarkt, QT-Verlängerung im EKG","Pulmonal-arterielle Hypertonie","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hirnblutung","Hepatitis (Leberentzündung)","Nierenversagen"],"selten":["Lungenembolie"],"unbekannt":["Interstitielle Lungenerkrankung","Reaktivierung einer Hepatitis B","Stevens-Johnson-Syndrom (schwere Hautreaktion)","Thrombotische Mikroangiopathie","Nephrotisches Syndrom"]},"schwangerschaft":"Nicht anwenden, ausser der Zustand der Frau erfordert es zwingend; beim Menschen wurden Fehlbildungen und schwere Wassereinlagerungen beim Ungeborenen beschrieben. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Tabletten täglich zur gleichen Zeit ganz schlucken, unabhängig von den Mahlzeiten; keine Grapefruit und kein Grapefruitsaft.","Blutbild in den ersten zwei Monaten wöchentlich, danach monatlich kontrollieren.","Atemnot, Brustschmerzen, trockenen Husten oder rasche Gewichtszunahme (Wassereinlagerung) ärztlich melden.","Säureblocker (z. B. Pantoprazol) nur nach Rücksprache einnehmen; Antazida mit 2 Stunden Abstand."],"darreichung":["Filmtabletten"]},"datopotamab-deruxtecan":{"wirkmechanismus":"Bringt ein Zellgift gezielt in Tumorzellen. Datopotamab Deruxtecan besteht aus einem humanisierten Antikörper gegen TROP2, ein Oberflächenprotein vieler Brust- und Lungentumoren, und dem Topoisomerase-I-Hemmer DXd (ein Abkömmling von Exatecan). Nach der Aufnahme in die Zelle wird DXd abgespalten, verursacht DNA-Schäden und führt zum Zelltod; weil es die Zellmembran durchdringt, kann es auch benachbarte Tumorzellen schädigen.","nebenwirkungen":{"sehrHaeufig":["Stomatitis (Mundschleimhautentzündung)","Übelkeit, Erbrechen, Verstopfung","Müdigkeit, Appetitlosigkeit","Alopezie (Haarausfall)","Trockene Augen, Keratitis (Hornhautentzündung)","Anämie (Blutarmut)"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis","Konjunktivitis (Bindehautentzündung), verschwommenes Sehen","Hautausschlag, Juckreiz","Infusionsbedingte Reaktionen"]},"schwangerschaft":"Kann das Ungeborene schädigen (enthält ein Zellgift); in der Schwangerschaft nicht anwenden. Frauen verhüten während und 7 Monate, Männer 4 Monate nach der letzten Dosis.","stillzeit":"Während und 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Neuer oder zunehmender Husten, Atemnot oder Fieber sofort melden (Lungenentzündung durch das Medikament).","Mehrmals täglich konservierungsmittelfreie Tränenersatzmittel verwenden; keine Kontaktlinsen.","Vorbeugend kortisonhaltige Mundspülung nach Anweisung; Mundschmerzen oder Schluckbeschwerden melden."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"daunorubicin":{"wirkmechanismus":"Schädigt die Erbsubstanz von Krebszellen und hemmt deren Teilung. Daunorubicin lagert sich zwischen die Basenpaare der DNA ein (Interkalation) und hemmt die Topoisomerase II, wodurch DNA-Strangbrüche entstehen. Zusätzlich bilden sich freie Radikale, die unter anderem für die Herzschädigung verantwortlich gemacht werden.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung (Mangel an weissen und roten Blutkörperchen und an Blutplättchen)","Infektionen","Haarausfall","Übelkeit, Erbrechen","Mundschleimhautentzündung, Durchfall","Rotfärbung des Urins (1–2 Tage nach der Gabe)","Fieber"],"unbekannt":["Herzmuskelschädigung mit Herzinsuffizienz (dosisabhängig, auch Jahre später)","Herzrhythmusstörungen, Herzbeutelentzündung","Sekundäre akute myeloische Leukämie, myelodysplastisches Syndrom","Schwere Gewebeschäden bei Paravasat, Venenentzündung","Anaphylaxie und andere Überempfindlichkeitsreaktionen","Hyperurikämie (erhöhte Harnsäure)","Bauchschmerzen, Magen-Darm-Geschwüre","Ausbleiben der Regelblutung, verminderte Spermienzahl"]},"schwangerschaft":"Nicht anwenden; Daunorubicin kann das Ungeborene schädigen. Frauen und Männer müssen während der Behandlung und mehrere Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Der Urin kann sich 1–2 Tage nach der Gabe rötlich färben – das ist harmlos.","Frühere Behandlungen mit Anthrazyklinen oder Bestrahlung angeben: die lebenslange Gesamtdosis ist wegen des Herzrisikos begrenzt.","Schmerzen oder Brennen an der Infusionsstelle sofort melden.","Blutbild und Herzfunktion werden regelmässig kontrolliert; Atemnot, Herzklopfen oder geschwollene Beine melden."],"darreichung":["Pulver zur Herstellung einer Injektions- bzw. Infusionslösung"]},"daunorubicin-cytarabin-liposomal":{"wirkmechanismus":"Enthält zwei Chemotherapeutika in einem festen Verhältnis in winzigen Fettbläschen (Liposomen), die bevorzugt von Leukämiezellen im Knochenmark aufgenommen werden. Daunorubicin, ein Anthrazyklin, lagert sich in die DNA ein und hemmt die Topoisomerase II; Cytarabin wird in die DNA eingebaut und hemmt die DNA-Synthese. Das Molverhältnis von 1:5 (Daunorubicin zu Cytarabin) wirkt synergistisch, und die Liposomen halten es im Körper über längere Zeit aufrecht.","nebenwirkungen":{"sehrHaeufig":["Febrile Neutropenie, Thrombozytopenie, Neutropenie, Anämie","Infektionen (z. B. Lungenentzündung, Sepsis)","Blutungen","Übelkeit, Durchfall, Verstopfung, Erbrechen, Bauchschmerzen, Schleimhautentzündung","Fieber, Ödeme, Müdigkeit, Schüttelfrost","Hautausschlag, Überempfindlichkeitsreaktionen","Kopfschmerzen, Schlafstörungen, Schwindel","Herzrhythmusstörungen, Blutdruckabfall, Atemnot, Husten"],"haeufig":["Herzschädigung (Kardiotoxizität, z. B. Herzinsuffizienz)"],"unbekannt":["Gewebeschädigung bei Extravasation"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich (fruchtschädigend). Frauen und Männer müssen während und bis 6 Monate nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Nicht austauschbar mit anderen Daunorubicin- oder Cytarabin-Präparaten (andere Dosierung).","Vor Beginn wird die Herzfunktion untersucht; das Blutbild wird regelmässig kontrolliert.","Fieber, Blutungen oder Infektzeichen sofort melden."],"darreichung":["Pulver zur Herstellung eines Konzentrats für eine Infusionslösung"]},"decitabin":{"wirkmechanismus":"Reaktiviert in Leukämiezellen Gene, die das Zellwachstum kontrollieren, und hemmt so die Vermehrung der Krebszellen. Decitabin ist ein Desoxycytidin-Analogon, das nach Phosphorylierung in die DNA eingebaut wird und dort die DNA-Methyltransferasen hemmt. Dies führt zu einer Hypomethylierung der DNA, zur Wiederanschaltung stillgelegter Gene und zur Ausreifung (Differenzierung) oder zum Absterben der Zellen.","nebenwirkungen":{"sehrHaeufig":["Lungenentzündung, Harnwegsinfekte und andere Infektionen","Febrile Neutropenie, Neutropenie, Thrombozytopenie, Anämie, Leukopenie","Kopfschmerzen","Nasenbluten","Durchfall, Erbrechen, Übelkeit","Fieber"],"haeufig":["Sepsis","Nasennebenhöhlenentzündung","Panzytopenie (Mangel an allen Blutzellen)","Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Mundschleimhautentzündung","Erhöhte Leberwerte und Bilirubin"],"gelegentlich":["Sweet-Syndrom (akute fieberhafte Hauterkrankung)"],"unbekannt":["Differenzierungssyndrom","Interstitielle Lungenerkrankung","Enterokolitis, inkl. neutropenischer Kolitis","Kardiomyopathie (Herzmuskelerkrankung)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; Decitabin kann das Ungeborene schädigen. Frauen müssen während und bis 6 Monate, Männer während und bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Blutbild vor jedem Behandlungszyklus kontrollieren lassen.","Bei Fieber, Infektzeichen oder Blutungen sofort das Behandlungsteam informieren.","Müdigkeit und Blutarmut können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"defibrotid":{"wirkmechanismus":"Schützt die Innenwand der kleinen Blutgefässe in der Leber und hilft, Blutgerinnsel aufzulösen. Defibrotid ist ein Gemisch aus Oligonukleotiden, das aus der Darmschleimhaut von Schweinen gewonnen wird. Es stabilisiert die durch Chemotherapie oder Bestrahlung geschädigten Endothelzellen, fördert die Fibrinolyse (mehr Gewebe-Plasminogenaktivator t-PA, weniger Plasminogenaktivator-Inhibitor PAI-1) und wirkt antithrombotisch und entzündungshemmend.","nebenwirkungen":{"haeufig":["Blutdruckabfall (Hypotonie)","Blutungen, z. B. im Magen-Darm-Trakt, in der Lunge, im Gehirn oder an der Katheterstelle","Nasenbluten","Blut im Urin (Hämaturie), Bluterbrechen","Übelkeit, Erbrechen, Durchfall","Hautausschlag, Juckreiz","Gerinnungsstörung (Koagulopathie)","Fieber"],"gelegentlich":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie (schwere allergische Reaktion)","Blutung in den Brustkorb (Hämatothorax)","Bluterguss im Gehirn","Bindehautblutung","Blaue Flecken und punktförmige Hautblutungen","Blutungen im Mund"]},"schwangerschaft":"Nicht anwenden, ausser der Zustand der Frau erfordert es zwingend; im Tierversuch traten blutungsbedingte Fehlgeburten auf. Frauen und Männer sollen während und bis 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Unbekannt, ob Defibrotid in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung (Abstillen oder Verzicht auf die Behandlung).","hinweise":["Wird im Spital alle 6 Stunden als 2-stündige Infusion in die Vene gegeben, in der Regel während mindestens 21 Tagen.","Während der Behandlung engmaschig auf Blutungen und Blutdruckabfall überwachen; bei relevanter Blutung Infusion unterbrechen.","Andere blutverdünnende Mittel nur nach Rücksprache mit dem Behandlungsteam."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"degarelix":{"wirkmechanismus":"Senkt rasch den Testosteronspiegel und entzieht damit dem Prostatakrebs den Wachstumsreiz. Degarelix blockiert als GnRH-Antagonist kompetitiv die GnRH-Rezeptoren der Hirnanhangdrüse (Hypophyse), sodass weniger LH und FSH ausgeschüttet werden. Dadurch fällt das Testosteron innerhalb weniger Tage auf Kastrationsniveau, ohne den anfänglichen Testosteronanstieg (Flare), wie er bei GnRH-Agonisten auftritt.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Schwellung, Verhärtung)"],"haeufig":["Anämie (Blutarmut)","Gewichtszunahme, Müdigkeit, grippeähnliche Beschwerden, Fieber, Schüttelfrost","Schlaflosigkeit, Schwindel, Kopfschmerzen","Durchfall, Übelkeit","Erhöhte Leberwerte","Vermehrtes Schwitzen (auch nachts), Hautausschlag","Muskel- und Gelenkbeschwerden","Gynäkomastie, Hodenschrumpfung, Erektionsstörungen"],"gelegentlich":["Überempfindlichkeitsreaktionen","Erhöhter Blutzucker, Diabetes","Herzrhythmusstörungen (z. B. Vorhofflimmern), QT-Verlängerung","Osteoporose (Knochenschwund)","Depression, Libidoverlust","Bluthochdruck"],"selten":["Herzinfarkt, Herzinsuffizienz","Anaphylaktische Reaktionen","Fieber bei Neutropenie","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nicht zutreffend – Degarelix ist nur für Männer bestimmt.","stillzeit":"Nicht zutreffend – nicht zur Anwendung bei Frauen bestimmt.","hinweise":["Wird monatlich unter die Bauchhaut gespritzt; Einstichstelle wechseln, nicht dort spritzen, wo Gürtel oder Hosenbund drücken.","Knochendichte, Blutzucker und Blutfette regelmässig kontrollieren.","Herzklopfen, Ohnmacht oder starken Schwindel ärztlich melden."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"delgocitinib":{"wirkmechanismus":"Dämpft Entzündung und Juckreiz der Haut an den Händen. Delgocitinib hemmt alle vier Januskinasen (JAK1, JAK2, JAK3 und TYK2) und blockiert damit die Signalübertragung zahlreicher entzündungsfördernder Botenstoffe über den JAK-STAT-Weg. Dadurch gehen Entzündung und Juckreiz zurück und die gestörte Hautbarriere kann sich erholen. Über die Haut gelangen nur sehr geringe Mengen ins Blut.","nebenwirkungen":{"haeufig":["Reaktionen an der Auftragsstelle (z. B. Schmerzen, Juckreiz, Rötung, Kribbeln)"]},"schwangerschaft":"Nur begrenzte Daten; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Delgocitinib in die Muttermilch übergeht; ein Risiko für den Säugling ist nicht auszuschliessen – nur nach ärztlicher Abwägung.","hinweise":["Zweimal täglich eine dünne Schicht auf die betroffenen Stellen an Händen und Handgelenken auftragen.","Nach dem Auftragen nicht in die Augen fassen.","Rückfettende Handpflege und Schutz vor Reizstoffen (z. B. Handschuhe bei Feuchtarbeit) weiterführen."],"darreichung":["Creme"]},"dengue-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen alle vier Typen des Denguevirus zu bilden. Der Impfstoff enthält ein lebendes, abgeschwächtes Dengue-Typ-2-Virus sowie drei abgeschwächte Mischviren, die die Oberflächeneiweisse der Typen 1, 3 und 4 tragen. Diese lösen eine Antikörper- und zelluläre Immunantwort aus. Gegen die Typen 3 und 4 ist eine Schutzwirkung bei Personen ohne frühere Dengue-Infektion nicht belegt.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Rötung an der Einstichstelle","Kopfschmerzen","Muskelschmerzen","Unwohlsein, Schwäche","Infekte der oberen Atemwege","Bei Kindern: Fieber, Appetitlosigkeit, Reizbarkeit, Schläfrigkeit"],"haeufig":["Nasen-Rachen-Entzündung","Gelenkschmerzen","Schwellung, Bluterguss oder Juckreiz an der Einstichstelle","Grippeähnliche Beschwerden"],"gelegentlich":["Schwindel","Durchfall, Übelkeit, Bauchschmerzen, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Müdigkeit"],"sehrSelten":["Angioödem (Schwellung von Gesicht oder Rachen)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Kontraindiziert. Nach der Impfung soll während mindestens 1 Monat eine Schwangerschaft vermieden werden.","stillzeit":"Kontraindiziert.","hinweise":["Zwei Dosen unter die Haut im Abstand von 3 Monaten; die Impfserie möglichst vor der Abreise abschliessen.","Die Impfung schützt nicht vollständig: weiterhin konsequenter Mückenschutz (Repellentien, lange Kleidung, Moskitonetz).","Gemäss Schweizer Empfehlungen in erster Linie für Reisende, die bereits eine nachgewiesene Dengue-Infektion durchgemacht haben.","Bei Fieber, starken Kopf- oder Gliederschmerzen oder Ausschlag nach einer Tropenreise ärztlich abklären lassen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"denosumab":{"wirkmechanismus":"Bremst den Knochenabbau, indem es ein Signal blockiert, das die knochenabbauenden Zellen aktiviert. Denosumab ist ein humaner monoklonaler Antikörper, der an RANKL bindet und so dessen Andocken an den Rezeptor RANK auf Osteoklasten und deren Vorläuferzellen verhindert. Dadurch werden Bildung, Funktion und Überleben der Osteoklasten gehemmt; Knochendichte und -festigkeit nehmen zu. Anders als Bisphosphonate lagert sich Denosumab nicht im Knochen ein – nach dem Absetzen lässt die Wirkung rasch nach.","nebenwirkungen":{"sehrHaeufig":["Glieder-, Muskel- und Knochenschmerzen","Hypokalzämie (Calciummangel; unter Xgeva sehr häufig, unter Prolia selten, aber teils schwer)","Atemnot und Durchfall (unter Xgeva)"],"haeufig":["Harnwegsinfekte und Infekte der oberen Atemwege","Ischiasschmerzen","Verstopfung, Bauchbeschwerden","Hautausschlag, Ekzem, Haarausfall","Kiefernekrose (Absterben von Kieferknochen; unter Xgeva häufig, unter Prolia selten)","Hypophosphatämie (Phosphatmangel) und vermehrtes Schwitzen (unter Xgeva)"],"gelegentlich":["Zellulitis (bakterielle Hautinfektion)","Divertikulitis","Ohrinfektion","Lichenoider Arzneimittelausschlag"],"selten":["Atypische Oberschenkelbrüche","Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Osteonekrose des äusseren Gehörgangs"],"unbekannt":["Mehrere Wirbelbrüche nach dem Absetzen von Prolia","Hyperkalzämie nach dem Absetzen bei wachsendem Skelett (Xgeva)"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung und bis mindestens 5 Monate nach der letzten Dosis wirksam verhüten.","stillzeit":"Unbekannt, ob Denosumab in die Muttermilch übergeht; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Zusätzlich Calcium und Vitamin D einnehmen (ausser bei erhöhtem Calcium); der Calciumspiegel wird vor jeder Dosis bzw. bei Nierenerkrankung engmaschig kontrolliert.","Prolia-Spritze alle 6 Monate pünktlich; nie ohne ärztlich geplante Anschlussbehandlung (meist ein Bisphosphonat) absetzen.","Vor Beginn Zahnstatus kontrollieren und auf gute Mundhygiene achten; Zahnbehandlungen mitteilen.","Bei Muskelkrämpfen oder Kribbeln (Calciummangel), geröteter, schmerzhafter Haut mit Fieber oder neuen Oberschenkelschmerzen ärztlichen Rat einholen."],"darreichung":["Injektionslösung (Fertigspritze)","Injektionslösung (Durchstechflasche)"]},"dequaliniumchlorid":{"wirkmechanismus":"Tötet Bakterien und andere Keime in der Scheide ab. Dequaliniumchlorid ist eine oberflächenaktive quaternäre Ammoniumverbindung, die sich an die Zellhülle von Mikroorganismen anlagert, deren Durchlässigkeit erhöht und Enzyme der Zelle hemmt; dadurch sterben die Keime ab. Es wirkt breit gegen grampositive und gramnegative Bakterien sowie Pilze und Trichomonaden und wird kaum ins Blut aufgenommen.","nebenwirkungen":{"haeufig":["Vaginaler Ausfluss","Juckreiz und Brennen im Scheiden- und Schambereich","Scheidenpilz (vaginale Candidose)"],"gelegentlich":["Kopfschmerzen","Übelkeit","Scheidenblutung oder Schmerzen in der Scheide","Entzündung von Scheide oder Schamlippen"],"unbekannt":["Allergische Reaktionen (Nesselsucht, Rötung, Ausschlag, Schwellung)","Geschwüre oder Schleimhautschäden in der Scheide","Blasenentzündung","Fieber"]},"schwangerschaft":"Kann nach ärztlicher Verordnung angewendet werden; der Wirkstoff gelangt kaum in den Körper.","stillzeit":"Kann angewendet werden.","hinweise":["Abends vor dem Schlafengehen in Rückenlage mit leicht angezogenen Beinen tief in die Scheide einführen.","Die Behandlung nicht vorzeitig abbrechen, auch wenn die Beschwerden schon abgeklungen sind (Rückfallgefahr).","Während der Behandlung eine Slipeinlage verwenden; Tablettenreste können austreten."],"darreichung":["Vaginaltabletten"]},"desfluran":{"wirkmechanismus":"Schaltet Bewusstsein und Schmerzwahrnehmung während einer Operation aus. Desfluran verstärkt hemmende Signale an GABA-A- und Glycinrezeptoren und dämpft erregende Signalwege im Zentralnervensystem. Wegen seiner sehr geringen Löslichkeit im Blut flutet es besonders schnell an und ab, sodass Narkosetiefe und Aufwachen gut steuerbar sind. Es wird praktisch unverändert abgeatmet.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen"],"haeufig":["Husten, Atemanhalten, Apnoe (Atemstillstand)","Laryngospasmus (Stimmritzenkrampf), vermehrter Speichelfluss","Pharyngitis (Rachenentzündung)","Kopfschmerzen","Konjunktivitis (Bindehautentzündung)","Bradykardie oder Tachykardie, Knotenrhythmus (Herzrhythmusstörung)","Bluthochdruck"],"gelegentlich":["Unruhe (Agitation), Schwindel","Herzinfarkt, Durchblutungsstörung des Herzmuskels","Hypoxie (Sauerstoffmangel)","Muskelschmerzen","Gefässerweiterung"],"unbekannt":["Maligne Hyperthermie","Hyperkaliämie mit Herzrhythmusstörungen","Leberentzündung bis Leberversagen","Rhabdomyolyse (Muskelzerfall)","Krampfanfälle","Herzstillstand"]},"schwangerschaft":"Nur bei klarer Notwendigkeit. In der Geburtshilfe kann Desfluran die Gebärmutter entspannen und den Blutverlust erhöhen.","stillzeit":"Es ist nicht bekannt, ob Desfluran in die Muttermilch übergeht; Anwendung in der Stillzeit mit Vorsicht.","hinweise":["Wird nur durch Anästhesiefachpersonen mit Narkosegerät und Überwachung verabreicht.","Vor der Narkose angeben, wenn bei Ihnen oder Blutsverwandten eine maligne Hyperthermie oder Probleme bei früheren Narkosen aufgetreten sind.","Nach einer Narkose mindestens 24 Stunden kein Fahrzeug lenken, keine Maschinen bedienen und keinen Alkohol trinken."],"darreichung":["Flüssigkeit zur Herstellung eines Dampfs zur Inhalation"]},"desloratadin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin und lindert dadurch Niesen, Fliessschnupfen, Juckreiz und Quaddeln. Desloratadin ist der aktive Hauptmetabolit von Loratadin und ein lang wirksamer, selektiver Antagonist peripherer Histamin-H1-Rezeptoren. In Laborversuchen hemmt es zusätzlich die Freisetzung entzündungsfördernder Botenstoffe aus Mastzellen. Es gelangt kaum ins Gehirn und macht deshalb selten müde.","nebenwirkungen":{"haeufig":["Müdigkeit","Mundtrockenheit","Kopfschmerzen","Bei Kleinkindern: Durchfall, Fieber, Schlaflosigkeit"],"sehrSelten":["Anaphylaxie und andere Überempfindlichkeitsreaktionen","Halluzinationen, Schwindel, Schläfrigkeit, psychomotorische Unruhe","Krampfanfälle","Herzrasen (Tachykardie), Herzklopfen","Bauchschmerzen, Übelkeit, Erbrechen, Verdauungsstörungen","Erhöhte Leberwerte, Hepatitis (Leberentzündung)","Muskelschmerzen"],"unbekannt":["QT-Verlängerung im EKG","Lichtempfindlichkeit der Haut","Verhaltensauffälligkeiten, Aggressivität","Gelbsucht","Gewichtszunahme, Appetitsteigerung"]},"schwangerschaft":"Viele Daten ohne Hinweis auf Fehlbildungen; vorsichtshalber möglichst vermeiden.","stillzeit":"Geht in die Muttermilch über; ärztlich abwägen, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen.","Vor Allergie-Hauttests ärztlich klären, wann abgesetzt werden muss.","Selten Müdigkeit möglich – die eigene Reaktion vor dem Autofahren prüfen."],"darreichung":["Filmtabletten"]},"desmopressin":{"wirkmechanismus":"Bewirkt, dass die Nieren mehr Wasser zurückhalten und weniger, dafür konzentrierteren Urin bilden. Desmopressin ist ein synthetisch abgewandeltes Vasopressin (antidiuretisches Hormon) und aktiviert gezielt die V2-Rezeptoren in den Sammelrohren der Niere; dadurch werden Wasserkanäle (Aquaporine) eingebaut und Wasser zurückgewonnen. Im Gegensatz zu Vasopressin wirkt es kaum gefässverengend und deutlich länger. In höherer Dosis setzt es zudem Gerinnungsfaktor VIII und von-Willebrand-Faktor aus den Gefässwänden frei und verbessert so die Blutgerinnung.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Hyponatriämie (Natriummangel im Blut), v. a. bei Erwachsenen über 65 Jahre","Schwindel","Übelkeit, Bauchschmerzen, Durchfall, Verstopfung, Erbrechen","Mundtrockenheit","Ödeme (Wassereinlagerungen), Müdigkeit"],"gelegentlich":["Schlaflosigkeit oder Schläfrigkeit","Herzklopfen, Blutdruckabfall beim Aufstehen","Hautausschlag, Juckreiz","Muskelkrämpfe","Gewichtszunahme","Stimmungsschwankungen, Aggressivität (bei Kindern)"],"selten":["Verwirrtheit"],"unbekannt":["Schwere Hyponatriämie mit Krampfanfällen, Hirnödem und Bewusstlosigkeit (Wasservergiftung)","Anaphylaktische Reaktionen","Gesichtsrötung, Pulsanstieg und Blutdruckschwankungen nach Injektion"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Die Erfahrungen bei Schwangeren mit Diabetes insipidus zeigen keine schädlichen Wirkungen auf Schwangerschaft oder Kind.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist in der Regel möglich.","hinweise":["Bei Bettnässen und Nykturie ab 1 Stunde vor bis 8 Stunden nach der Einnahme möglichst wenig trinken – sonst droht eine Wasservergiftung.","Bei Erbrechen, Durchfall, Fieber oder starkem Durst die Einnahme unterbrechen; bei Kopfschmerzen, Übelkeit, Verwirrtheit oder rascher Gewichtszunahme sofort ärztlich das Natrium kontrollieren lassen.","Schmelztabletten unter der Zunge zergehen lassen, ohne Wasser; Tabletten, Schmelztabletten und Nasenspray sind unterschiedlich dosiert und nicht 1:1 austauschbar."],"darreichung":["Tabletten","Schmelztabletten (Lyophilisat)","Nasenspray","Injektionslösung"]},"desogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Desogestrel ist eine Vorstufe (Prodrug) und wird in Darmwand und Leber zum eigentlichen Wirkstoff Etonogestrel umgewandelt. In der Dosis von 75 Mikrogramm täglich hemmt es – anders als ältere Minipillen – in den allermeisten Zyklen den Eisprung; zusätzlich verdickt es den Schleim am Gebärmutterhals. Da kein Östrogen enthalten ist, steigt das Thromboserisiko nach heutigem Wissen kaum.","nebenwirkungen":{"haeufig":["Unregelmässige Blutungen, Ausbleiben der Regel","Stimmungsschwankungen, depressive Verstimmung, verminderte Libido","Kopfschmerzen","Übelkeit","Akne","Brustschmerzen","Gewichtszunahme"],"gelegentlich":["Scheideninfektion","Unverträglichkeit von Kontaktlinsen","Erbrechen","Haarausfall","Schmerzhafte Regelblutung, Eierstockzysten","Müdigkeit"],"selten":["Hautausschlag, Nesselsucht","Erythema nodosum (entzündliche Hautknoten)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Angioödem","Absonderung aus der Brust"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft absetzen. Eine versehentliche Einnahme erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Erlaubt: Milchmenge und -qualität werden nicht beeinträchtigt; sehr geringe Mengen gehen in die Muttermilch über.","hinweise":["Täglich etwa zur gleichen Zeit ohne Pause einnehmen. Bei mehr als 12 Stunden Verspätung ist der Schutz vermindert: Tablette sofort nachnehmen und 7 Tage zusätzlich ein Kondom verwenden.","Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden nach der Einnahme gilt wie eine vergessene Tablette.","Unregelmässige Blutungen sind häufig, besonders in den ersten Monaten; anhaltende oder starke Blutungen ärztlich abklären.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"desoximetason":{"wirkmechanismus":"Dämpft Entzündung, Juckreiz, Rötung und Schwellung der Haut. Desoximetason ist ein stark wirksames, fluoriertes Glukokortikoid, das an Glukokortikoidrezeptoren in den Hautzellen bindet und die Bildung entzündungsfördernder Botenstoffe wie Prostaglandine und Zytokine hemmt. Es verengt zudem die Blutgefässe der Haut und bremst eine übermässige Zellteilung.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz, Reizung oder Trockenheit der Haut","Allergische Kontaktdermatitis","Hautverdünnung (Atrophie), Dehnungsstreifen und erweiterte Äderchen (Teleangiektasien) bei längerer Anwendung","Periorale Dermatitis, steroidbedingte Akne, Haarbalgentzündung (Follikulitis)","Verstärkte Behaarung oder Aufhellung der Haut an der Anwendungsstelle","Verschleierung oder Ausbreitung von Hautinfektionen","Unterdrückung der Nebennierenfunktion bei grossflächiger Anwendung","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; nicht grossflächig, nicht langfristig und nicht unter luftdichten Verbänden anwenden, besonders im ersten Schwangerschaftsdrittel.","stillzeit":"Nur nach ärztlicher Abwägung und kleinflächig; nicht im Brustbereich auftragen.","hinweise":["Dünn und nur so lange wie verordnet auftragen; nicht unter luftdichten Verbänden.","Im Gesicht nur kurz und auf ärztliche Anweisung anwenden; nicht in die Augen bringen.","Nach dem Auftragen die Hände waschen (ausser wenn die Hände behandelt werden)."],"darreichung":["Salbe","Fettsalbe"]},"desvenlafaxin":{"wirkmechanismus":"Hebt die Stimmung, indem es die Botenstoffe Serotonin und Noradrenalin im Gehirn erhöht. Desvenlafaxin – der wichtigste wirksame Abbaustoff von Venlafaxin – hemmt die Wiederaufnahme von Serotonin und Noradrenalin, ohne nennenswert an Muskarin-, Histamin- oder Alpha-Rezeptoren zu binden. Es wird überwiegend an Glucuronsäure gekoppelt, nur zu einem kleinen Teil über CYP3A4 abgebaut und zu einem grossen Teil unverändert über die Niere ausgeschieden; CYP2D6 spielt kaum eine Rolle.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schwindel","Mundtrockenheit","Vermehrtes Schwitzen","Schlaflosigkeit","Obstipation (Verstopfung)"],"haeufig":["Appetitminderung, Gewichtsveränderung","Müdigkeit, Schläfrigkeit","Zittern, Missempfindungen","Verschwommenes Sehen, Ohrensausen","Herzklopfen, Herzrasen, Blutdruckanstieg","Durchfall, Erbrechen","Sexuelle Funktionsstörungen (Libidoabnahme, Ejakulations-, Orgasmus- und Erektionsstörungen)","Angst, Nervosität, ungewöhnliche Träume, Gähnen"],"gelegentlich":["Überempfindlichkeitsreaktionen","Ohnmacht (Synkope)","Blutdruckabfall beim Aufstehen","Nasenbluten","Harnverhalt","Erhöhte Blutfette (Cholesterin, Triglyceride)","Bewegungsstörungen (extrapyramidale Störungen)"],"selten":["Hyponatriämie (Natriummangel)","Krampfanfälle","Serotoninsyndrom","Manie oder Hypomanie","Halluzinationen","Angioödem"],"unbekannt":["Stevens-Johnson-Syndrom (schwere Hautreaktion)","Stress-Kardiomyopathie (Takotsubo)","Interstitielle Lungenerkrankung, eosinophile Pneumonie","Blutungen (Haut, Schleimhaut, Magen-Darm-Trakt)","Suizidgedanken und suizidales Verhalten","Absetzsymptome (Schwindel, Übelkeit, Missempfindungen, Reizbarkeit)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Einnahme in der Spätschwangerschaft kann beim Neugeborenen Anpassungsstörungen verursachen und das Risiko für Blutungen nach der Geburt erhöhen.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Retardtabletten ganz schlucken, nicht teilen oder zerkauen; die leere Tablettenhülle kann im Stuhl erscheinen.","Blutdruck vor Beginn und regelmässig während der Behandlung kontrollieren.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung (Absetzsymptome).","Die stimmungsaufhellende Wirkung setzt meist nach 2–4 Wochen ein."],"darreichung":["Retardtabletten"]},"deucravacitinib":{"wirkmechanismus":"Dämpft die Entzündung in der Haut, indem es in den Zellen die Signalweiterleitung wichtiger Entzündungsbotenstoffe unterbricht. Deucravacitinib bindet allosterisch an die regulatorische (Pseudokinase-)Domäne der Tyrosinkinase 2 (TYK2), einer Kinase der JAK-Familie, und hemmt sie sehr selektiv. TYK2 vermittelt die Signale von Interleukin-23, Interleukin-12 und Typ-I-Interferonen. Die Kinasen JAK1, JAK2 und JAK3 werden in therapeutischer Dosis kaum gehemmt.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (z. B. Erkältung, Halsentzündung)"],"haeufig":["Lippen- und Mundherpes (Herpes simplex)","Mundgeschwüre (Aphthen)","Akneähnlicher Ausschlag","Haarbalgentzündung (Follikulitis)","Erhöhte CK (Muskelenzym)"],"gelegentlich":["Gürtelrose (Herpes zoster)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Deucravacitinib in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen; Tabletten ganz schlucken, nicht zerdrücken oder teilen.","Vor Beginn Tuberkulose-Test; bei Fieber oder anhaltenden Infektzeichen ärztlich abklären lassen.","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Filmtabletten"]},"dexamethason":{"wirkmechanismus":"Dämpft Entzündungen, allergische Reaktionen und die Abwehrreaktionen des Immunsystems sehr stark. Dexamethason ist ein synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor im Zellinneren bindet und die Ablesung zahlreicher Gene verändert: Entzündungsbotenstoffe wie Zytokine und Prostaglandine werden vermindert gebildet, Abwehrzellen gehemmt und durchlässige Gefässe abgedichtet. Es wirkt etwa 25- bis 30-mal stärker entzündungshemmend als körpereigenes Cortisol, hat praktisch keine salzzurückhaltende (mineralokortikoide) Wirkung und wirkt lange. Darum eignet es sich besonders bei Hirnödem und zur Vorbeugung von Übelkeit bei Chemotherapie.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Augeninnendruck und Bindehautblutung (Augenimplantat)"],"haeufig":["Katarakt (grauer Star), Augenschmerzen, Glaskörpertrübungen (Augenimplantat)","Augenbeschwerden wie Brennen und Stechen (Augentropfen)"],"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung, verschwommenes Sehen (z. B. Chorioretinopathie)","Überempfindlichkeitsreaktionen bis zur Anaphylaxie (v. a. bei Injektion)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Dexamethason gelangt über die Plazenta zum Kind; bei längerer Behandlung sind Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in die Muttermilch über. Bei kurzer Anwendung meist vertretbar; bei höheren Dosen oder Langzeitbehandlung ärztlich abklären, ob abgestillt werden soll.","hinweise":["Tabletten morgens mit dem Frühstück einnehmen (weniger Magenbeschwerden und Schlafstörungen).","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Augentropfen nur kurzzeitig und unter augenärztlicher Kontrolle anwenden; weiche Kontaktlinsen vorher herausnehmen."],"darreichung":["Tabletten","Injektionslösung","Augentropfen","Intravitreales Implantat (Augenimplantat)"]},"dexamethason-neomycin-polymyxin-b":{"wirkmechanismus":"Hemmt die Entzündung und bekämpft gleichzeitig Bakterien am Auge. Dexamethason ist ein stark wirksames Glukokortikoid, das die Bildung entzündungsfördernder Botenstoffe unterdrückt und Schwellung, Rötung und Juckreiz lindert. Neomycin ist ein Aminoglykosid-Antibiotikum, das die bakterielle Eiweisssynthese an den Ribosomen stört. Polymyxin B schädigt die Zellmembran gramnegativer Bakterien, einschliesslich Pseudomonas aeruginosa.","nebenwirkungen":{"gelegentlich":["Keratitis (Hornhautentzündung)","Erhöhter Augeninnendruck","Verschwommenes Sehen, Lichtempfindlichkeit","Pupillenerweiterung, hängendes Augenlid","Augenschmerzen, Augenschwellung, Juckreiz, Fremdkörpergefühl","Augenreizung, Augenrötung, vermehrter Tränenfluss"],"unbekannt":["Überempfindlichkeitsreaktionen, v. a. allergische Kontaktreaktion auf Neomycin","Kopfschmerzen","Hornhautgeschwür","Glaukom und Linsentrübung (Katarakt) bei längerer Anwendung","Pilz- oder Virusinfektionen des Auges (Sekundärinfektion)","Verzögerte Wundheilung"]},"schwangerschaft":"Keine ausreichenden Daten; Aminoglykoside können bei systemischer Gabe das Gehör des Ungeborenen schädigen. Nur bei klarer Notwendigkeit und kurzzeitig anwenden.","stillzeit":"Nicht bekannt, ob die Wirkstoffe nach Anwendung am Auge in die Muttermilch gelangen; nur nach ärztlicher Abwägung.","hinweise":["Augentropfen vor Gebrauch gut schütteln.","Nicht länger als ärztlich verordnet anwenden; bei Anwendung über 10 Tage den Augeninnendruck kontrollieren lassen.","Während der Behandlung keine Kontaktlinsen tragen."],"darreichung":["Augentropfen (Suspension)","Augensalbe"]},"dexamfetamin":{"wirkmechanismus":"Steigert Aufmerksamkeit und Konzentration und dämpft Impulsivität, indem es die Botenstoffe Dopamin und Noradrenalin im Gehirn vermehrt. Dexamfetamin, die wirksamere rechtsdrehende Form von Amphetamin, hemmt die Wiederaufnahme dieser Botenstoffe und setzt sie zusätzlich aktiv aus den Nervenendigungen frei. Ausserhalb des Gehirns wirkt es sympathomimetisch: Puls und Blutdruck steigen.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Nervosität"],"haeufig":["Appetitminderung, verminderte Gewichts- und Grössenzunahme bei Kindern","Reizbarkeit, Aggressivität, Angst, Depression, abnormes Verhalten","Kopfschmerzen, Schwindel, Überaktivität, Dyskinesien (unwillkürliche Bewegungen)","Herzrasen, Herzklopfen, Herzrhythmusstörungen","Veränderungen von Blutdruck und Puls (meist Anstieg)","Bauchschmerzen, Übelkeit, Erbrechen, Mundtrockenheit","Gelenkschmerzen"],"selten":["Angina pectoris (Brustenge)","Hautausschlag, Nesselsucht","Müdigkeit","Wachstumsverzögerung bei Langzeitanwendung"],"sehrSelten":["Halluzinationen, Psychose, suizidales Verhalten","Tics oder Verschlechterung bestehender Tics","Krampfanfälle, Hirnblutung, zerebrale Vaskulitis","Herzstillstand","Leberfunktionsstörungen bis Leberkoma","Erythema multiforme, exfoliative Dermatitis","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)"],"unbekannt":["Abhängigkeit, Missbrauch","Kardiomyopathie, Herzinfarkt, plötzlicher Tod","Schlaganfall","Raynaud-Phänomen (kalte, weisse Finger)","Ischämische Kolitis (Darmdurchblutungsstörung)","Schwere Überempfindlichkeitsreaktionen (Angioödem, Anaphylaxie)","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Amphetamine können beim Neugeborenen zu Entzugssymptomen, Frühgeburt und niedrigem Geburtsgewicht führen.","stillzeit":"Dexamfetamin geht in die Muttermilch über; nicht stillen.","hinweise":["Untersteht dem Betäubungsmittelgesetz: sicher und für andere unzugänglich aufbewahren, nicht weitergeben.","Die letzte Dosis nicht zu spät am Tag einnehmen (Schlafstörungen).","Vor Beginn und regelmässig Puls, Blutdruck, Gewicht und bei Kindern die Körpergrösse kontrollieren; die Notwendigkeit der Behandlung periodisch überprüfen.","Alkohol meiden; die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Tabletten"]},"dexibuprofen":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Dexibuprofen ist die rechtsdrehende Form (S-Enantiomer) von Ibuprofen, die praktisch allein für die Hemmung der Cyclooxygenasen COX-1 und COX-2 verantwortlich ist. Daher entspricht eine Dosis Dexibuprofen etwa der doppelten Menge des üblichen Ibuprofens (Racemat).","nebenwirkungen":{"haeufig":["Dyspepsie (Verdauungsbeschwerden), Bauchschmerzen, Übelkeit, Erbrechen, Durchfall, Blähungen","Müdigkeit, Schläfrigkeit, Kopfschmerzen, Schwindel","Hautausschlag"],"gelegentlich":["Magen-Darm-Geschwüre und -Blutungen, Gastritis, Mundschleimhautentzündung","Schlaflosigkeit, Angst, Unruhe","Sehstörungen, Ohrensausen (Tinnitus)","Nesselsucht, Juckreiz, Hautblutungen (Purpura)","Schnupfen, Bronchospasmus (Verkrampfung der Atemwege)","Angioödem"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Psychotische Reaktionen, Depression, Reizbarkeit","Hepatitis, Gelbsucht","Hörstörungen"],"sehrSelten":["Agranulozytose, aplastische Anämie, Thrombozytopenie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Akutes Nierenversagen","Aseptische Meningitis (nicht-bakterielle Hirnhautentzündung)"],"unbekannt":["Ödeme, Bluthochdruck, Herzinsuffizienz","Erhöhtes Risiko für Herzinfarkt und Schlaganfall bei hohen Dosen"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach strenger ärztlicher Abwägung; ab der 20. Woche können NSAR die Nierenfunktion des Ungeborenen beeinträchtigen. Im letzten Drittel kontraindiziert.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; kurzfristige Anwendung nur nach ärztlicher Abwägung, bei längerer Anwendung abstillen.","hinweise":["Dexibuprofen wirkt etwa doppelt so stark wie die gleiche Menge Ibuprofen – nicht zusammen mit Ibuprofen einnehmen; Höchstdosis 1200 mg pro Tag.","Mit einer Mahlzeit und reichlich Flüssigkeit einnehmen; so kurz und so niedrig dosiert wie möglich.","Schwindel und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Bei schwarzem Stuhl, Bluterbrechen oder starken Magenschmerzen sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"dexmedetomidin":{"wirkmechanismus":"Beruhigt und dämpft, ohne die Atmung wesentlich zu beeinträchtigen. Dexmedetomidin ist ein hochselektiver Agonist an Alpha-2-Adrenozeptoren; im Hirnstamm (Locus coeruleus) vermindert es die Freisetzung von Noradrenalin und bewirkt so eine schlafähnliche, leicht weckbare Sedierung. Es wirkt zudem schmerzlindernd und senkt durch die verminderte Sympathikusaktivität Puls und Blutdruck; bei rascher Gabe kann der Blutdruck zunächst durch Gefässverengung ansteigen.","nebenwirkungen":{"sehrHaeufig":["Bradykardie (langsamer Puls)","Hypotonie (tiefer Blutdruck)","Hypertonie (hoher Blutdruck)"],"haeufig":["Myokardischämie oder Herzinfarkt","Tachykardie (Herzrasen)","Übelkeit, Erbrechen","Mundtrockenheit","Hyperglykämie oder Hypoglykämie (zu hoher oder zu tiefer Blutzucker)","Unruhe (Agitiertheit)","Entzugssyndrom nach dem Absetzen","Erhöhte Körpertemperatur (Hyperthermie)"],"gelegentlich":["AV-Block 1. Grades","Vermindertes Herzzeitvolumen, Herzstillstand","Atemnot, Atemstillstand (Apnoe)","Halluzinationen","Metabolische Azidose (Übersäuerung des Blutes)","Geblähter Bauch","Durst"],"unbekannt":["Polyurie (vermehrte Harnausscheidung)"]},"schwangerschaft":"Nicht anwenden, ausser wenn es eindeutig erforderlich ist.","stillzeit":"Dexmedetomidin geht in die Muttermilch über; 24 Stunden nach Ende der Infusion ist es kaum mehr nachweisbar. Über das Stillen entscheidet die Ärztin oder der Arzt.","hinweise":["Wird nur im Spital unter fortlaufender Überwachung von Herz, Kreislauf und Atmung angewendet.","Nach längerer Anwendung können beim Absetzen Unruhe und Blutdruckanstieg auftreten."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"dexmethylphenidat":{"wirkmechanismus":"Verbessert Aufmerksamkeit und Impulskontrolle, indem es die Botenstoffe Dopamin und Noradrenalin im Gehirn verstärkt. Dexmethylphenidat ist das pharmakologisch wirksame d-threo-Enantiomer von Methylphenidat. Es blockiert die Transporter für Dopamin (DAT) und Noradrenalin (NET) und hemmt so die Wiederaufnahme dieser Botenstoffe in die Nervenzelle; ihre Konzentration im synaptischen Spalt steigt, besonders im Stirnhirn und im Striatum. Der Abbau erfolgt hauptsächlich durch Esterasen (nicht über CYP-Enzyme).","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schlaflosigkeit","Nervosität"],"haeufig":["Appetitminderung und Gewichtsabnahme","Bauchschmerzen, Übelkeit, Erbrechen, Mundtrockenheit","Herzklopfen, Tachykardie (schneller Puls), Blutdruckanstieg","Angst, Reizbarkeit, Aggressivität, Stimmungsschwankungen","Schwindel","Hautausschlag, Juckreiz"],"gelegentlich":["Psychotische Symptome, Halluzinationen","Verschwommenes Sehen","Brustschmerzen"],"selten":["Angina pectoris (Brustenge)"],"sehrSelten":["Herzinfarkt, Herzstillstand, plötzlicher Herztod","Krampfanfälle","Entzündung der Hirngefässe (zerebrale Vaskulitis)","Thrombozytopenie und Leukopenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Schwere Hautreaktionen (Erythema multiforme, exfoliative Dermatitis)","Schwere Leberfunktionsstörungen"],"unbekannt":["Auftreten oder Verstärkung von Tics","Suizidgedanken","Priapismus (schmerzhafte Dauererektion)","Raynaud-Phänomen (weisse, kalte Finger oder Zehen)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; Anwendung nicht empfohlen, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Methylphenidat geht in die Muttermilch über; ärztlich abwägen, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Morgens einnehmen; Kapseln ganz schlucken oder den Inhalt auf etwas Apfelmus streuen – nicht zerkauen.","Betäubungsmittel mit Missbrauchspotenzial: sicher aufbewahren und nicht weitergeben.","Blutdruck, Puls, Körpergrösse und Gewicht regelmässig kontrollieren; Alkohol meiden.","Kann die Fahrtüchtigkeit beeinträchtigen (Schwindel, Sehstörungen)."],"darreichung":["Retardkapseln"]},"dexpanthenol":{"wirkmechanismus":"Fördert die Regeneration von Haut und Schleimhäuten. Dexpanthenol wird in der Haut rasch in Pantothensäure (Vitamin B5) umgewandelt, einen Baustein des Coenzyms A, das die Zellen für Stoffwechsel und Zellteilung brauchen. Es regt die Neubildung der obersten Hautschicht (Epithelisierung) an, verbessert die Feuchtigkeitsbindung der Haut und lindert Juckreiz leicht.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen; bei Bepanthen Plus (Chlorhexidin) auch schwere allergische Reaktionen bis Anaphylaxie (allergischer Schock)","Kontaktdermatitis, Ekzem an der Auftragsstelle","Juckreiz, Rötung, Ausschlag oder Nesselsucht","Hautreizung, Bläschen"]},"schwangerschaft":"Kann angewendet werden; bei bestimmungsgemässer Anwendung sind keine Risiken bekannt.","stillzeit":"Kann angewendet werden, auch zur Pflege wunder Brustwarzen. Bepanthen Plus (mit Chlorhexidin) nicht auf die Brustwarzen auftragen.","hinweise":["Wunden, die sich nach einigen Tagen nicht bessern oder Entzündungszeichen zeigen (Rötung, Schwellung, Eiter, Fieber), ärztlich beurteilen lassen.","Bepanthen Plus enthält das Desinfektionsmittel Chlorhexidin: nicht zusammen mit Seifen oder anderen Desinfektionsmitteln auf derselben Stelle anwenden.","Augen- und Nasensalbe: nach dem Einbringen ins Auge kurzzeitig verschwommenes Sehen – erst wieder Auto fahren, wenn die Sicht klar ist."],"darreichung":["Salbe","Creme","Augen- und Nasensalbe"]},"dextromethorphan":{"wirkmechanismus":"Dämpft den Hustenreflex im Hirnstamm. Dextromethorphan ist ein Morphinan-Abkömmling ohne relevante Wirkung an μ-Opioidrezeptoren und deshalb ohne schmerzstillende Wirkung. Es wirkt am Sigma-1-Rezeptor, blockiert NMDA-Rezeptoren und hemmt die Wiederaufnahme von Serotonin. Abgebaut wird es vor allem über CYP2D6 zu Dextrorphan; bei langsamen Metabolisierern wirkt es stärker und länger.","nebenwirkungen":{"haeufig":["Müdigkeit, Benommenheit","Schwindel","Übelkeit, Erbrechen, Magen-Darm-Beschwerden"],"sehrSelten":["Halluzinationen","Abhängigkeit bei Missbrauch","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Angioödem, Bronchospasmus)"],"unbekannt":["Serotonin-Syndrom (Fieber, Unruhe, Muskelzuckungen, Durchfall), v. a. in Kombination mit serotonergen Mitteln","Bei Überdosierung: Verwirrtheit, Erregung, Sprach- und Bewegungsstörungen, Atemdämpfung"]},"schwangerschaft":"Im 1. Drittel nicht anwenden; danach nur kurzfristig nach ärztlicher Abwägung. Hohe Dosen kurz vor der Geburt können beim Neugeborenen die Atmung dämpfen.","stillzeit":"Nicht anwenden; der Übergang in die Muttermilch ist ungenügend untersucht und eine Atemdämpfung beim Säugling nicht auszuschliessen.","hinweise":["Nur bei trockenem Reizhusten und nur wenige Tage anwenden; bei Husten länger als 1–2 Wochen, Fieber oder Atemnot ärztlich abklären.","Vor der Einnahme in der Apotheke Antidepressiva und andere Dauermedikamente angeben (Serotonin-Syndrom).","Kein Alkohol; die Fahrtüchtigkeit kann beeinträchtigt sein.","Missbrauchsgefahr: hohe Dosen wirken berauschend und sind gefährlich – ausser Reichweite von Kindern und Jugendlichen aufbewahren."],"darreichung":["Sirup","Tabletten","Lösung zum Einnehmen (Kombipräparat)"]},"diamorphin":{"wirkmechanismus":"Stillt bei schwer opioidabhängigen Menschen das Verlangen nach Opioiden und verhindert Entzugserscheinungen. Diamorphin ist ein Prodrug: Im Körper wird es rasch zu 6-Monoacetylmorphin und Morphin umgewandelt, die als Agonisten am µ-Opioidrezeptor wirken. Wegen seiner hohen Fettlöslichkeit gelangt es schneller ins Gehirn als Morphin, was den raschen Wirkungseintritt erklärt.","nebenwirkungen":{"unbekannt":["Atemdepression, besonders bei Überdosierung oder Beikonsum","Krampfanfälle","Juckreiz und Hautrötung (Histaminfreisetzung)","Übelkeit, Erbrechen, Verstopfung","Schläfrigkeit, Benommenheit","Blutdruckabfall, langsamer Puls","Starkes Schwitzen","Harnverhalt"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; ein Entzug gefährdet das Ungeborene. Beim Neugeborenen sind Entzugssymptome und eine Atemdepression möglich.","stillzeit":"Diamorphin geht als Morphin in die Muttermilch über; Stillen wird nicht empfohlen.","hinweise":["Abgabe und Einnahme bzw. Injektion nur unter Aufsicht in bewilligten Zentren; nach der Gabe wird die Person überwacht.","Kein Beikonsum von Alkohol, Beruhigungsmitteln oder Drogen – Gefahr einer tödlichen Atemlähmung.","Nicht Auto fahren und keine Maschinen bedienen, solange die Wirkung anhält."],"darreichung":["Pulver zur Herstellung einer Injektionslösung","Tabletten","Retardtabletten"]},"diazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend, muskelentspannend und krampflösend. Diazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt so die Wirkung des hemmenden Botenstoffs GABA (häufigere Öffnung des Chloridkanals). Es wird in der Leber v. a. über CYP2C19 und CYP3A4 zu ebenfalls wirksamen Abbauprodukten wie Desmethyldiazepam umgewandelt, das sehr lange im Körper bleibt; bei wiederholter Einnahme kann sich die Wirkung daher anhäufen.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit (Somnolenz)"],"haeufig":["Müdigkeit","Ataxie (Gangunsicherheit), gestörte Bewegungskoordination, Zittern","Verwirrtheit","Entzugserscheinungen beim Absetzen"],"gelegentlich":["Anterograde Amnesie (Gedächtnislücken)","Konzentrations- und Gleichgewichtsstörungen, Schwindel, Kopfschmerzen, verwaschene Sprache","Muskelschwäche","Übelkeit, Verstopfung, Durchfall","Allergische Hautreaktionen (Juckreiz, Rötung, Ausschlag)"],"selten":["Atemdepression bis Atemstillstand","Paradoxe Reaktionen (Unruhe, Aggressivität, Halluzinationen)","Bradykardie, Blutdruckabfall, Ohnmacht","Harnverhalt, Inkontinenz","Libidoveränderungen"],"sehrSelten":["Leukopenie (Verminderung der weissen Blutkörperchen)","Erhöhte Leberwerte, Gelbsucht"],"unbekannt":["Körperliche und psychische Abhängigkeit","Stürze und Knochenbrüche, v. a. bei älteren Menschen","Venenreizung und Venenentzündung an der Injektionsstelle"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Bei Anwendung gegen Ende der Schwangerschaft oder während der Geburt können beim Neugeborenen Muskelschlaffheit, Atemprobleme, Unterkühlung und Entzugssymptome auftreten.","stillzeit":"Diazepam geht in die Muttermilch über und kann sich beim Säugling anreichern (Müdigkeit, Trinkschwäche). Nicht stillen.","hinweise":["So kurz wie möglich anwenden (bei Angst höchstens 8–12 Wochen einschliesslich Ausschleichen) – Gefahr von Gewöhnung und Abhängigkeit.","Nach längerer Einnahme nicht abrupt absetzen, sondern langsam ausschleichen (Entzugssymptome, Krampfanfälle).","Kein Alkohol; die Fahrtüchtigkeit kann auch noch am Folgetag beeinträchtigt sein.","Ältere Menschen: erhöhte Sturzgefahr, besonders nachts."],"darreichung":["Tabletten","Tropfen","Injektionslösung","Rektallösung (Rektaltuben)"]},"diclofenac":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung entzündungsfördernder Botenstoffe hemmt. Diclofenac hemmt reversibel die Cyclooxygenasen COX-1 und COX-2 (mit gewisser COX-2-Präferenz) und damit die Synthese von Prostaglandinen. Die Hemmung von COX-1 in Magenschleimhaut und Niere erklärt die typischen Magen-Darm- und Nierennebenwirkungen; die COX-2-Hemmung trägt zum erhöhten Herz-Kreislauf-Risiko bei.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Dyspepsie (Verdauungsbeschwerden), Blähungen, Appetitlosigkeit","Erhöhte Leberwerte (Transaminasen)","Hautausschlag","Gel und Pflaster: Rötung, Juckreiz oder Ekzem an der Auftragsstelle"],"gelegentlich":["Herzinfarkt, Herzinsuffizienz, Herzklopfen, Brustschmerzen (v. a. bei hoher Dosis und Langzeitanwendung)"],"selten":["Magen-Darm-Geschwüre und -Blutungen (Bluterbrechen, Teerstuhl)","Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Asthmaanfälle","Hepatitis, Gelbsucht","Nesselsucht","Ödeme (Wassereinlagerungen)","Schläfrigkeit"],"sehrSelten":["Blutbildstörungen bis Agranulozytose (Ausfall der weissen Blutkörperchen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Fulminante Hepatitis, Leberversagen","Akutes Nierenversagen, nephrotisches Syndrom","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)","Sehstörungen, Ohrensausen (Tinnitus)","Bluthochdruck, Vaskulitis (Gefässentzündung)","Pankreatitis, Kolitis"],"unbekannt":["Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Ischämische Kolitis (Darmentzündung durch Minderdurchblutung)"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich (ab der 20. Woche Risiko für Nierenschäden beim Kind und Fruchtwassermangel). Im letzten Drittel kontraindiziert.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in der Stillzeit möglichst meiden, eine kurze Anwendung nur nach ärztlicher Abwägung.","hinweise":["So niedrig dosiert und so kurz wie möglich anwenden; rezeptfreie Präparate ohne ärztlichen Rat nur wenige Tage einnehmen.","Tabletten unzerkaut mit Flüssigkeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","Gel nicht auf offene Wunden, Schleimhäute oder Augen auftragen und danach die Hände waschen.","Kann Schwindel und Müdigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Magensaftresistente Tabletten","Retardtabletten","Zäpfchen","Injektionslösung","Gel","Pflaster","Augentropfen"]},"dienogest":{"wirkmechanismus":"Lässt Endometriose-Herde schrumpfen, indem es eine dauerhafte Gestagenwirkung erzeugt und die Östrogenbildung dämpft. Dienogest bindet stark an Progesteronrezeptoren und wirkt an der Gebärmutterschleimhaut kräftig gestagen; zugleich hat es eine antiandrogene, aber keine androgene Wirkung. Bei täglicher Einnahme senkt es die Hormonausschüttung der Eierstöcke mässig, sodass ein östrogenarmes, gestagenbetontes Milieu entsteht. Das Gewebe der Endometrioseherde wird zunächst umgewandelt (Dezidualisierung) und bildet sich dann zurück.","nebenwirkungen":{"haeufig":["Uterine Blutungen, Schmierblutungen, verändertes Blutungsmuster","Kopfschmerzen, Migräne","Depressive Verstimmung, Stimmungsschwankungen, Schlafstörungen, Nervosität, Reizbarkeit","Libidoverlust","Brustbeschwerden","Gewichtszunahme","Übelkeit, Bauchschmerzen, Blähungen","Akne, Haarausfall","Hitzewallungen","Ovarialzysten (Eierstockzysten)","Rückenschmerzen, Schwäche"],"gelegentlich":["Anämie (Blutarmut)","Angst, Depression","Trockene Augen, Ohrensausen","Herzklopfen, tiefer Blutdruck","Atemnot","Durchfall, Verstopfung","Trockene Haut, Juckreiz, vermehrte Behaarung","Scheidenpilz, Harnwegsinfektionen","Wassereinlagerungen (Ödeme)"]},"schwangerschaft":"Nicht anwenden: Eine Endometriose muss in der Schwangerschaft nicht behandelt werden, und es gibt nur sehr wenige Daten.","stillzeit":"Nicht empfohlen – Dienogest geht in die Muttermilch über.","hinweise":["Täglich ohne Pause etwa zur gleichen Zeit einnehmen.","Visanne ist kein Verhütungsmittel: Falls Verhütung nötig ist, eine nichthormonale Methode (z. B. Kondom) verwenden.","Bei Erbrechen oder Durchfall innerhalb von 3–4 Stunden nach der Einnahme kann die Wirkung vermindert sein.","Unregelmässige Blutungen sind besonders in den ersten Monaten häufig; anhaltend starke Blutungen ärztlich abklären lassen."],"darreichung":["Tabletten"]},"diflucortolon":{"wirkmechanismus":"Dämpft Entzündung, Juckreiz, Rötung und Schwellung der Haut. Diflucortolonvalerat ist ein stark wirksames, fluoriertes Glukokortikoid, das an Glukokortikoidrezeptoren in den Hautzellen bindet und die Bildung entzündungsfördernder Botenstoffe hemmt. Es verengt zudem die Blutgefässe der Haut und bremst eine übermässige Zellteilung. In der Kombination mit Isoconazol bekämpft dieses die Pilze, während Diflucortolon die Entzündung rasch lindert.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz, Reizung oder Trockenheit der Haut","Allergische Kontaktdermatitis","Hautverdünnung (Atrophie), Dehnungsstreifen und erweiterte Äderchen (Teleangiektasien) bei längerer Anwendung","Periorale Dermatitis, steroidbedingte Akne, Haarbalgentzündung (Follikulitis)","Verstärkte Behaarung oder Aufhellung der Haut an der Anwendungsstelle","Verschleierung oder Ausbreitung von Hautinfektionen","Unterdrückung der Nebennierenfunktion bei grossflächiger Anwendung","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; nicht grossflächig, nicht langfristig und nicht unter luftdichten Verbänden anwenden, besonders im ersten Schwangerschaftsdrittel.","stillzeit":"Nur nach ärztlicher Abwägung und kleinflächig; nicht im Brustbereich auftragen.","hinweise":["Dünn und nur so lange wie verordnet auftragen; nicht unter luftdichten Verbänden.","Travocort nur, bis die Entzündung abgeklungen ist (höchstens etwa 2 Wochen), danach mit einem kortisonfreien Pilzmittel weiterbehandeln.","Nicht in die Augen bringen; nach dem Auftragen die Hände waschen."],"darreichung":["Creme","Salbe","Fettsalbe"]},"digoxin":{"wirkmechanismus":"Verlangsamt einen zu schnellen Puls und verstärkt die Pumpkraft des Herzmuskels. Digoxin hemmt die Natrium-Kalium-Pumpe (Na+/K+-ATPase) der Herzmuskelzellen; dadurch steigt über den Natrium-Calcium-Austauscher die Calciumkonzentration in der Zelle, was die Kontraktionskraft erhöht (positiv inotrop). Zusätzlich verstärkt Digoxin den Einfluss des Vagusnervs und verlangsamt so die Überleitung im AV-Knoten, wodurch bei Vorhofflimmern weniger Impulse auf die Herzkammern übertragen werden. Die therapeutische Breite ist sehr eng; Digoxin wird überwiegend unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Durchfall","Schwindel und andere Störungen des Nervensystems","Sehstörungen (verschwommenes Sehen, Gelb- oder Grünsehen)","Herzrhythmusstörungen (z. B. Extraschläge, Bigeminus), Bradykardie (verlangsamter Herzschlag) und Leitungsstörungen","Hautausschlag (Nesselsucht-artig oder scharlachartig)"],"gelegentlich":["Depression"],"sehrSelten":["Thrombozytopenie (Mangel an Blutplättchen)","Appetitlosigkeit","Verwirrtheit, Apathie, Psychose","Kopfschmerzen","Gefährliche Herzrhythmusstörungen (Vorhof- und Kammertachykardien)","Durchblutungsstörung oder Absterben von Darmabschnitten (Darmischämie)","Gynäkomastie (Brustvergrösserung beim Mann) bei Langzeitbehandlung","Müdigkeit, Schwäche, Unwohlsein"]},"schwangerschaft":"Kann in der Schwangerschaft angewendet werden, wenn es nötig ist; Digoxin gelangt zum Kind. Der Spiegel muss überwacht werden, da sich der Bedarf ändern kann.","stillzeit":"Geht nur in geringer Menge in die Muttermilch über; Stillen ist erlaubt.","hinweise":["Regelmässige Kontrollen von Digoxinspiegel, Kalium und Nierenfunktion sind wichtig.","Warnzeichen einer Überdosierung: Übelkeit, Appetitlosigkeit, Sehstörungen (Gelb- oder Grünsehen), Verwirrtheit, sehr langsamer oder unregelmässiger Puls – sofort ärztlich melden.","Antazida und Colestyramin mit mindestens 2 Stunden Abstand einnehmen; keine Johanniskraut-Präparate.","Jedes neue Medikament, auch Antibiotika, ärztlich auf Wechselwirkungen prüfen lassen."],"darreichung":["Tabletten","Injektionslösung"]},"dihydralazin":{"wirkmechanismus":"Senkt den Blutdruck, indem es direkt die Muskulatur der kleinen Arterien (Arteriolen) entspannt. Der genaue Mechanismus ist nicht vollständig geklärt; Dihydralazin beeinflusst unter anderem die Calcium-Freisetzung in der glatten Gefässmuskulatur. Der periphere Widerstand sinkt; gegenregulatorisch steigen Herzfrequenz, Herzzeitvolumen und die Salz- und Wasserrückhaltung, weshalb es bei längerer Behandlung oft mit einem Betablocker und einem Diuretikum kombiniert wird.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Tachykardie (Herzrasen), Herzklopfen"],"haeufig":["Gesichtsrötung (Flush)","Hypotonie (Blutdruckabfall)","Angina-pectoris-ähnliche Beschwerden","Gelenk- und Muskelschmerzen, Gelenkschwellungen","Magen-Darm-Beschwerden (Übelkeit, Erbrechen, Durchfall)","Positive antinukleäre Antikörper (Laborbefund)"],"gelegentlich":["Lupus-ähnliches Syndrom (Gelenkschmerzen, Fieber, Hautausschlag)","Verstopfte Nase, tränende Augen","Ödeme (Wassereinlagerungen)","Schwindel"],"selten":["Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)","Hepatitis (Leberentzündung), Gelbsucht","Glomerulonephritis (Nierenentzündung)","Periphere Nervenentzündung (Kribbeln, Taubheit)"]},"schwangerschaft":"Wird zur Behandlung von schwerem Bluthochdruck in der Schwangerschaft eingesetzt (vor allem im 2. und 3. Drittel); im 1. Drittel nur nach strenger ärztlicher Abwägung.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Bei Gelenkschmerzen, Fieber, Hautausschlag oder Brustfellschmerzen ärztlich abklären lassen (Lupus-ähnliches Syndrom).","Bei der Injektion Blutdruck und Puls engmaschig überwachen; in der Schwangerschaft auch die Herztöne des Kindes.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen; Alkohol verstärkt die Wirkung."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"diltiazem":{"wirkmechanismus":"Entlastet das Herz, senkt den Blutdruck und verlangsamt den Puls, indem es den Calcium-Einstrom in Herz- und Gefässmuskelzellen hemmt. Diltiazem blockiert L-Typ-Calciumkanäle: Es erweitert die Herzkranz- und peripheren Arterien, verhindert Gefässkrämpfe und senkt so den Sauerstoffbedarf des Herzens. Zusätzlich bremst es die Erregungsbildung im Sinusknoten und die Überleitung im AV-Knoten. Diltiazem wird über CYP3A4 abgebaut und hemmt dieses Enzym mässig.","nebenwirkungen":{"sehrHaeufig":["Periphere Ödeme (Wassereinlagerungen, vor allem an den Knöcheln)"],"haeufig":["Kopfschmerzen, Schwindel","AV-Block (verlangsamte Erregungsleitung im Herzen)","Herzklopfen","Flush (Gesichtsrötung mit Wärmegefühl)","Verstopfung, Verdauungsstörungen, Magenschmerzen, Übelkeit","Hautrötung (Erythem)","Unwohlsein, Müdigkeit"],"gelegentlich":["Bradykardie (langsamer Puls)","Blutdruckabfall beim Aufstehen","Nervosität, Schlaflosigkeit","Erbrechen, Durchfall","Erhöhte Leberwerte"],"selten":["Mundtrockenheit","Nesselsucht (Urtikaria)"],"unbekannt":["Sinusknotenstillstand, sinuatrialer Block, Herzstillstand, Verschlechterung einer Herzschwäche","Thrombozytopenie (Mangel an Blutplättchen)","Stimmungsschwankungen einschliesslich Depression; extrapyramidale Bewegungsstörungen","Hepatitis; Zahnfleischwucherung (Gingivahyperplasie)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, exfoliative Dermatitis)","Angioödem, Lichtempfindlichkeit, Vaskulitis (Gefässentzündung)","Brustvergrösserung beim Mann, vermehrtes Schwitzen"]},"schwangerschaft":"Kontraindiziert (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Diltiazem geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Retardform unzerkaut mit Flüssigkeit schlucken.","Puls regelmässig messen; bei sehr langsamem Puls, Schwindel oder Ohnmacht ärztlich melden.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Beginn der Behandlung.","Vor Operationen und beim Beginn neuer Medikamente die Einnahme angeben – Diltiazem hat viele Wechselwirkungen."],"darreichung":["Tabletten bzw. Kapseln mit verzögerter Freisetzung (Retardform)"]},"dimenhydrinat":{"wirkmechanismus":"Dämpft das Gleichgewichtsorgan und das Brechzentrum im Gehirn und lindert so die Reiseübelkeit. Dimenhydrinat ist ein Salz aus Diphenhydramin und 8-Chlortheophyllin; wirksam ist das Diphenhydramin. Es blockiert zentrale und periphere Histamin-H1-Rezeptoren und wirkt zusätzlich anticholinerg (an Muskarinrezeptoren), wodurch die Weiterleitung von Signalen aus dem Gleichgewichtsorgan zum Brechzentrum gehemmt wird. Weil es gut ins Gehirn gelangt, macht es deutlich müde.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit und Benommenheit","Schwindelgefühl"],"unbekannt":["Mundtrockenheit","Sehstörungen und Anstieg des Augeninnendrucks","Verstopfung und Magen-Darm-Beschwerden","Erschwertes Wasserlassen bis Harnverhalt","Paradoxe Erregung, Unruhe und Schlafstörungen (v. a. bei Kindern)","Allergische Hautreaktionen und Lichtempfindlichkeit","Leberfunktionsstörungen (cholestatischer Ikterus)","Blutbildveränderungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Im letzten Schwangerschaftsdrittel nicht anwenden, da Dimenhydrinat vorzeitige Wehen auslösen kann.","stillzeit":"Geht in die Muttermilch über und kann beim Säugling Unruhe oder Schläfrigkeit verursachen – in der Stillzeit nicht empfohlen.","hinweise":["Zur Vorbeugung rechtzeitig vor Reisebeginn anwenden (Zeitpunkt gemäss Packungsbeilage).","Macht müde: keinen Alkohol trinken, nicht selbst Auto fahren und keine Maschinen bedienen.","Höchstdosis nicht überschreiten: Überdosierung kann Halluzinationen, Krampfanfälle und Herzrhythmusstörungen auslösen; Missbrauch ist möglich."],"darreichung":["Kaugummi","Tabletten (Kombipräparat)"]},"dimethylfumarat":{"wirkmechanismus":"Dämpft überschiessende Entzündungs- und Immunreaktionen. Dimethylfumarat wird im Darm rasch in Monomethylfumarat umgewandelt, den eigentlichen Wirkstoff. Dieser aktiviert den Nrf2-Signalweg, der Zellen vor oxidativem Stress schützt, hemmt entzündungsfördernde Signale (NF-kappaB) und verschiebt die Immunantwort von entzündlichen Th1- und Th17-Zellen hin zu Th2-Zellen. Zudem sinkt die Zahl der Lymphozyten im Blut.","nebenwirkungen":{"sehrHaeufig":["Flush (Hitzegefühl mit Hautrötung)","Durchfall, Übelkeit","Bauchschmerzen, Blähungen","Lymphopenie und Leukopenie (Mangel an weissen Blutkörperchen; vor allem unter Psoriasis-Therapie sehr häufig)"],"haeufig":["Erbrechen, Verdauungsbeschwerden, Magenschleimhautentzündung, Magen-Darm-Infekt","Juckreiz, Ausschlag, Hautrötung, Brennen der Haut","Kopfschmerzen, Kribbeln (Parästhesien)","Erhöhte Leberwerte","Eiweiss und Ketone im Urin (Proteinurie, Ketonurie)","Müdigkeit, Schwäche, Hitzegefühl","Eosinophilie (Anstieg bestimmter weisser Blutkörperchen)","Appetitminderung","Haarausfall (Alopezie)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Thrombozytopenie (Mangel an Blutplättchen)","Schwindel","Erhöhtes Kreatinin im Blut"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Gürtelrose (Herpes zoster) und andere opportunistische Infektionen","Anaphylaxie, Angioödem, Atemnot","Arzneimittelbedingte Leberschädigung","Fanconi-Syndrom (Nierenschaden)","Laufende Nase"]},"schwangerschaft":"Multiple Sklerose: nur nach sorgfältiger ärztlicher Abwägung, wenn klar notwendig. Psoriasis-Präparat (Skilarence): kontraindiziert, Frauen im gebärfähigen Alter müssen sicher verhüten.","stillzeit":"Unklar, ob der Wirkstoff in die Muttermilch übergeht: bei MS nur nach ärztlicher Abwägung; das Psoriasis-Präparat ist in der Stillzeit kontraindiziert.","hinweise":["Mit einer Mahlzeit einnehmen und unzerkaut schlucken – das mildert Flush und Magen-Darm-Beschwerden; die Dosis wird zu Beginn langsam gesteigert.","Blutbild (Lymphozyten) vor Beginn und regelmässig, mindestens alle 3 Monate, sowie Leber- und Nierenwerte und Urin kontrollieren lassen.","Neue oder zunehmende neurologische Beschwerden (Schwäche, Seh-, Sprach- oder Gedächtnisstörungen) sofort melden.","Keine hochprozentigen alkoholischen Getränke innerhalb einer Stunde nach der Einnahme."],"darreichung":["Magensaftresistente Hartkapseln (Multiple Sklerose)","Magensaftresistente Tabletten (Psoriasis)"]},"dimetinden":{"wirkmechanismus":"Lindert Juckreiz und allergische Beschwerden, indem es den Botenstoff Histamin blockiert. Dimetinden ist ein Antagonist am Histamin-H1-Rezeptor und vermindert so Gefässdurchlässigkeit, Quaddelbildung, Rötung und Juckreiz. Auf der Haut wirkt es zusätzlich leicht örtlich betäubend, weshalb das Gel Juckreiz rasch lindert. Eingenommen gelangt es ins Gehirn und macht deshalb müde; zudem hat es schwache anticholinerge Wirkungen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit (Tropfen)"],"haeufig":["Schläfrigkeit, Benommenheit (Tropfen)","Nervosität (Tropfen)"],"selten":["Unruhe, Erregung","Kopfschmerzen, Schwindel","Übelkeit, Magen-Darm-Beschwerden","Mund- und Rachentrockenheit"],"sehrSelten":["Anaphylaktische Reaktionen mit Schwellung von Gesicht und Rachen","Hautausschlag","Muskelkrämpfe","Atembeschwerden"],"unbekannt":["Trockene Haut und Brennen an der Auftragsstelle (Gel)","Allergische Hautreaktionen (Gel)","Brennen und Trockenheit der Nasenschleimhaut (Vibrocil)"]},"schwangerschaft":"Tropfen nur nach ärztlicher Abwägung, besonders im 1. Drittel zurückhaltend. Gel kleinflächig nach Abwägung möglich, nicht auf grosse, entzündete oder verletzte Hautflächen.","stillzeit":"Tropfen nicht empfohlen (Übergang in die Muttermilch, Müdigkeit beim Säugling möglich). Gel nicht auf die Brust auftragen.","hinweise":["Die Tropfen machen müde: Fahrtüchtigkeit und Reaktionsvermögen können eingeschränkt sein, besonders zusammen mit Alkohol.","Gel: bei grossflächiger Anwendung behandelte Haut nicht der Sonne aussetzen; bei Juckreiz, der nach einigen Tagen nicht bessert oder grosse Flächen betrifft, Arzt aufsuchen.","Vibrocil (mit Phenylephrin) ohne ärztlichen Rat nicht länger als 7 Tage anwenden – sonst droht eine dauerhaft verstopfte Nase."],"darreichung":["Tropfen zum Einnehmen","Gel","Roll-on","Nasenspray, Nasentropfen, Nasengel (Kombi mit Phenylephrin)"]},"dinoproston":{"wirkmechanismus":"Macht den Gebärmutterhals weich und dehnbar und regt Wehen an. Dinoproston ist mit dem körpereigenen Prostaglandin E2 identisch. Es baut das Bindegewebe (Kollagen) im Gebärmutterhals um, sodass dieser verstreicht und sich öffnet, und steigert die Kontraktionsbereitschaft der Gebärmuttermuskulatur. Die Vaginaleinlage gibt den Wirkstoff gleichmässig über bis zu 24 Stunden ab und kann jederzeit entfernt werden.","nebenwirkungen":{"haeufig":["Überstimulation der Gebärmutter (zu starke oder zu häufige Wehen)","Veränderungen der kindlichen Herztöne, Gefährdung des Kindes (fetaler Stress)"],"gelegentlich":["Übelkeit, Erbrechen, Durchfall","Kopfschmerzen","Fieber","Tiefer Blutdruck","Brennen in der Scheide","Blutungen vor oder nach der Geburt"],"selten":["Disseminierte intravasale Gerinnung (schwere Gerinnungsstörung)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Gebärmutterriss","Fruchtwasserembolie","Schwellung im Genitalbereich"]},"schwangerschaft":"Nur am Ende der Schwangerschaft zur Geburtseinleitung im Spital unter ständiger Überwachung von Mutter und Kind. In früheren Schwangerschaftsstadien nicht zur Geburtseinleitung anwenden.","stillzeit":"Nicht relevant, da die Anwendung vor der Geburt erfolgt; Prostaglandin E2 wird im Körper rasch abgebaut.","hinweise":["Nur im Spital mit laufender Überwachung (CTG) und Möglichkeit zum notfallmässigen Kaiserschnitt.","Nach dem Einlegen 20–30 Minuten liegen bleiben.","Die Vaginaleinlage wird bei Beginn regelmässiger Wehen, Blasensprung, Überstimulation oder Gefährdung des Kindes entfernt, spätestens nach 24 Stunden."],"darreichung":["Vaginalinsert (Vaginaleinlage)","Vaginalgel"]},"dinutuximab-beta":{"wirkmechanismus":"Hilft dem Immunsystem, Neuroblastomzellen zu erkennen und zu zerstören. Dinutuximab beta ist ein chimärer (Maus/Mensch) monoklonaler IgG1-Antikörper gegen das Disialogangliosid GD2, das auf Neuroblastomzellen in grosser Menge vorkommt. Die Bindung löst eine komplementabhängige Zytotoxizität (CDC) und eine antikörperabhängige zellvermittelte Zytotoxizität (ADCC) durch Immunzellen aus. Weil GD2 auch auf schmerzleitenden Nervenfasern vorkommt, verursacht die Behandlung typischerweise starke Schmerzen.","nebenwirkungen":{"sehrHaeufig":["Fieber und Schüttelfrost","Schmerzen (v. a. Bauch-, Glieder- und Nervenschmerzen)","Überempfindlichkeitsreaktionen","Kapillarlecksyndrom, Ödeme (Wassereinlagerungen)","Hypotonie (Blutdruckabfall)","Blutbildveränderungen (Anämie, Thrombozytopenie, Neutropenie)","Erbrechen, Durchfall, Verstopfung","Juckreiz, Hautausschlag, Nesselsucht"],"haeufig":["Anaphylaktische Reaktion (schwere allergische Reaktion)","Sepsis (Blutvergiftung)","Periphere Neuropathie (Nervenschädigung), Krampfanfälle","Sehstörungen (erweiterte Pupillen, Lidschwellung)","Atemnot, Bronchospasmus (Verkrampfung der Atemwege), Lungenödem","Hypertonie (Bluthochdruck)","Elektrolytstörungen (Kalium, Natrium, Calcium oder Magnesium zu tief)","Appetitlosigkeit"],"unbekannt":["Transverse Myelitis (Rückenmarkentzündung)","Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerz, Sehstörung, Krampfanfälle)"]},"schwangerschaft":"Keine Erfahrungen; GD2 kommt im Nervengewebe des Ungeborenen vor. In der Schwangerschaft nicht anwenden; Frauen im gebärfähigen Alter verhüten während und bis 6 Monate nach der Behandlung.","stillzeit":"Während der Behandlung und bis 6 Monate nach der letzten Dosis nicht stillen.","hinweise":["Behandlung nur im Spital durch erfahrene Fachpersonen; eine Notfallausrüstung für allergische Reaktionen muss bereitstehen.","Schmerzmittel (auch Opioide) werden vorbeugend gegeben; Schmerzen sofort melden.","Sehstörungen, Schwäche oder Gefühlsstörungen in Armen und Beinen sowie Probleme beim Wasserlassen sofort melden (mögliche Nervenschäden).","Keine Impfungen bis 10 Wochen nach dem letzten Zyklus ohne Rücksprache mit dem Behandlungsteam."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"diosmectit":{"wirkmechanismus":"Bindet im Darm überschüssiges Wasser sowie Krankheitserreger und deren Giftstoffe und schützt die Darmschleimhaut. Diosmectit ist ein natürliches Tonmineral (Aluminium-Magnesium-Silikat) mit blättchenartiger Struktur und sehr grosser Oberfläche. Es legt sich als Schutzfilm über die Schleimhaut, wird weder aufgenommen noch verstoffwechselt und unverändert mit dem Stuhl ausgeschieden.","nebenwirkungen":{"haeufig":["Verstopfung"],"unbekannt":["Blähungen","Erbrechen","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Juckreiz, Angioödem)"]},"schwangerschaft":"Nur kurzfristig und nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","stillzeit":"Nur kurzfristig und nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","hinweise":["Pulver in Wasser einrühren und gleich trinken.","Mindestens 2 Stunden Abstand zu anderen Medikamenten einhalten.","Bei Durchfall viel trinken; bei Kindern und älteren Menschen Elektrolytlösungen zur Rehydratation verwenden.","Hält der Durchfall länger als 2 Tage an oder treten Fieber oder Blut im Stuhl auf, ärztlich abklären lassen."],"darreichung":["Pulver zur Herstellung einer Suspension zum Einnehmen (Beutel)"]},"diosmin":{"wirkmechanismus":"Stärkt die Venenwände und verringert Schwellungen in den Beinen. Die mikronisierte Flavonoidfraktion (90 % Diosmin, 10 % weitere Flavonoide, ausgedrückt als Hesperidin) erhöht die Spannung der Venenwand, indem sie die Wirkung von Noradrenalin an der Venenwand verlängert. Zudem vermindert sie die Durchlässigkeit und Brüchigkeit der kleinsten Blutgefässe (Kapillaren), hemmt das Anhaften weisser Blutkörperchen an der Gefässwand und die damit verbundene Entzündung und fördert den Lymphabfluss. Die Mikronisierung verbessert die Aufnahme aus dem Darm.","nebenwirkungen":{"haeufig":["Durchfall","Dyspepsie (Verdauungsbeschwerden)","Übelkeit, Erbrechen"],"gelegentlich":["Kolitis (Dickdarmentzündung)"],"selten":["Schwindel, Kopfschmerzen, Unwohlsein","Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["Bauchschmerzen","Schwellung von Gesicht, Lippen oder Augenlidern, ausnahmsweise Angioödem (Quincke-Ödem)"]},"schwangerschaft":"Im Tierversuch keine schädlichen Wirkungen, beim Menschen nur begrenzte Erfahrungen; vorsichtshalber in der Schwangerschaft möglichst nicht anwenden.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Zu den Mahlzeiten einnehmen.","Wirkt am besten zusammen mit Kompressionsstrümpfen, regelmässiger Bewegung, Hochlagern der Beine und Meiden von Hitze und langem Stehen.","Bei Hämorrhoidalattacken nur kurzfristig in der höheren Dosierung einnehmen; ohne rasche Besserung ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"diphtherie-tetanus-impfstoff-td":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen die Gifte der Tetanus- und Diphtherie-Bakterien zu bilden. Der Impfstoff enthält diese Gifte in unschädlich gemachter Form (Toxoide), gebunden an ein Aluminiumsalz zur Verstärkung der Immunantwort. Die Diphtherie-Komponente ist für ältere Kinder und Erwachsene reduziert («d»), um Lokalreaktionen zu vermindern. Der Impfstoff enthält keine Keuchhusten-Komponente.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung an der Einstichstelle"],"haeufig":["Verhärtung oder Knötchen an der Einstichstelle","Kopfschmerzen","Müdigkeit, Unwohlsein","Muskelschmerzen"],"gelegentlich":["Fieber","Schwindel","Übelkeit, Erbrechen","Geschwollene Lymphknoten","Gelenkschmerzen"],"unbekannt":["Allergische Reaktionen bis zur Anaphylaxie","Guillain-Barré-Syndrom, Brachialneuritis (Nervenentzündung des Armgeflechts)","Steriler Abszess an der Einstichstelle"]},"schwangerschaft":"Impfung ist möglich, wenn angezeigt (z. B. Tetanusschutz nach Verletzung); in der Schwangerschaft wird in der Regel dTpa mit Keuchhustenschutz bevorzugt.","stillzeit":"Impfung in der Stillzeit möglich.","hinweise":["Auffrischungen gemäss Schweizerischem Impfplan (Erwachsene in der Regel mit 25, 45 und 65 Jahren, danach alle 10 Jahre).","Bei Verletzungen den Impfausweis vorlegen – je nach letzter Impfung ist eine Auffrischung und evtl. Tetanus-Immunglobulin nötig.","Wo auch Keuchhustenschutz sinnvoll ist, wird meist ein dTpa-Impfstoff verwendet."],"darreichung":["Injektionssuspension (Fertigspritze, intramuskulär)"]},"diphtherie-tetanus-pertussis-impfstoff-dtpa":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen Diphtherie, Tetanus und Keuchhusten zu bilden. Der Impfstoff enthält unschädlich gemachte Bakteriengifte (Toxoide) von Diphtherie und Tetanus sowie gereinigte Bestandteile des Keuchhustenerregers (azelluläre Pertussis-Antigene) in reduzierter Menge, die für Auffrischimpfungen ausreicht. Bei Impfung in der Schwangerschaft gehen die mütterlichen Antikörper über die Plazenta auf das Kind über und schützen es in den ersten Lebensmonaten.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung an der Einstichstelle","Kopfschmerzen","Müdigkeit","Kinder: Reizbarkeit, Schläfrigkeit"],"haeufig":["Fieber","Schwindel","Übelkeit, Magen-Darm-Beschwerden, Appetitlosigkeit","Verhärtung oder Bluterguss an der Einstichstelle"],"gelegentlich":["Fieber über 39 °C","Geschwollene Lymphknoten","Gelenk- und Muskelschmerzen","Halsschmerzen, Husten","Juckreiz, Hautausschlag"],"unbekannt":["Allergische Reaktionen bis zur Anaphylaxie","Krampfanfälle","Kollaps oder schockähnlicher Zustand mit verminderter Ansprechbarkeit (bei Kindern)","Nesselsucht, Angioödem","Guillain-Barré-Syndrom und Nervenentzündung des Armgeflechts (Brachialneuritis)","Ausgedehnte Schwellung des geimpften Arms"]},"schwangerschaft":"Empfohlen in jeder Schwangerschaft, idealerweise im 2. Drittel (gemäss Schweizerischem Impfplan); schützt das Neugeborene vor Keuchhusten.","stillzeit":"Impfung in der Stillzeit möglich.","hinweise":["Auffrischung gemäss Schweizerischem Impfplan; Personen mit Kontakt zu Säuglingen sollten gegen Keuchhusten geschützt sein.","Für die Grundimmunisierung von Säuglingen nicht geeignet (dafür gibt es Kinderimpfstoffe).","Nach der Impfung etwa 15 Minuten in der Praxis bleiben."],"darreichung":["Injektionssuspension (Fertigspritze, intramuskulär)"]},"diphtherie-tetanus-pertussis-poliomyelitis-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen vier Krankheiten zu bilden. Der Impfstoff enthält unschädlich gemachte Bakteriengifte (Toxoide) von Diphtherie und Tetanus, gereinigte Bestandteile des Keuchhustenbakteriums (azelluläre Pertussis-Antigene) sowie abgetötete Polioviren der Typen 1, 2 und 3, gebunden an Aluminiumsalze. Die gebildeten Antikörper neutralisieren die Bakteriengifte bzw. die Polioviren. Präparate mit kleinem «d» und «p» enthalten weniger Diphtherie- und Pertussis-Antigen und sind für die Auffrischung ab dem Schulalter bestimmt.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung und Schwellung an der Einstichstelle","Müdigkeit, Kopfschmerzen","Reizbarkeit und Schläfrigkeit (bei Kindern)"],"haeufig":["Fieber","Appetitlosigkeit","Übelkeit, Erbrechen, Durchfall","Verhärtung oder Bluterguss an der Einstichstelle"],"gelegentlich":["Lymphknotenschwellung","Muskel- und Gelenkschmerzen","Schwindel"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Ausgedehnte Schwellung der geimpften Gliedmasse","Krampfanfälle mit oder ohne Fieber","Kollapsähnliche Zustände bei Kindern (hypoton-hyporesponsive Episode)","Nesselsucht"]},"schwangerschaft":"Die Keuchhustenimpfung wird in der Schweiz in jeder Schwangerschaft empfohlen, idealerweise im 2. Drittel (13.–26. Woche); die mütterlichen Antikörper schützen das Neugeborene. Bisherige Daten zeigen kein Risiko für das Kind.","stillzeit":"Impfung während der Stillzeit möglich.","hinweise":["Erwachsene: Auffrischung gegen Diphtherie und Tetanus in der Schweiz mit 25, 45 und 65 Jahren, danach alle 10 Jahre; Keuchhustenschutz besonders bei Kontakt mit Säuglingen.","Bei Verletzungen kann je nach Impfstatus eine vorzeitige Tetanus-Auffrischung nötig sein – Impfausweis mitbringen.","Fieber und Schmerzen an der Einstichstelle in den ersten 1–2 Tagen sind häufig und harmlos."],"darreichung":["Injektionssuspension in Fertigspritze"]},"dipyridamol":{"wirkmechanismus":"Macht die Blutplättchen weniger klebrig und erweitert die Blutgefässe. Dipyridamol hemmt die Wiederaufnahme von Adenosin in rote Blutkörperchen, Blutplättchen und Gefässwandzellen, sodass mehr Adenosin an seinen Rezeptoren wirkt. Zusätzlich hemmt es Phosphodiesterasen in den Blutplättchen; beides erhöht dort cAMP bzw. cGMP und vermindert die Plättchenverklumpung. Zusammen mit ASS, die über einen anderen Weg (Cyclooxygenase) wirkt, wird die Plättchenhemmung verstärkt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (v. a. zu Beginn)","Schwindel","Übelkeit, Durchfall","Bauchschmerzen, Verdauungsbeschwerden"],"haeufig":["Erbrechen","Muskelschmerzen","Verstärkung von Angina-pectoris-Beschwerden","Blutungen, z. B. Nasenbluten oder Magen-Darm-Blutungen (in Kombination mit ASS)"],"unbekannt":["Herzrasen (Tachykardie), Blutdruckabfall, Hitzegefühl","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Bronchospasmus, Angioödem)","Hirnblutung (in Kombination mit ASS)","Einlagerung von Dipyridamol in Gallensteine","Verstärkte Blutungen während oder nach Operationen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Das Kombipräparat mit ASS ist im letzten Schwangerschaftsdrittel kontraindiziert.","stillzeit":"Dipyridamol geht in geringen Mengen in die Muttermilch über; Anwendung nur, wenn klar notwendig.","hinweise":["Kopfschmerzen sind zu Beginn häufig und lassen meist nach einigen Tagen nach; Kapseln ganz schlucken.","Beim Kombipräparat mit ASS gelten zusätzlich alle Gegenanzeigen der Acetylsalicylsäure (z. B. aktive Magengeschwüre, Blutungsneigung, Analgetika-Asthma).","Vor Operationen, Zahnbehandlungen oder einem Herz-Stresstest die Einnahme angeben."],"darreichung":["Retardkapseln (Kombination mit Acetylsalicylsäure)"]},"diroximelfumarat":{"wirkmechanismus":"Dämpft fehlgeleitete Entzündungsreaktionen, die bei multipler Sklerose das Nervensystem schädigen. Diroximelfumarat wird im Körper rasch zu Monomethylfumarat umgewandelt, demselben Wirkmetaboliten wie bei Dimethylfumarat. Monomethylfumarat aktiviert den Nrf2-Signalweg (antioxidativer Zellschutz), wirkt entzündungshemmend und verschiebt die Immunantwort weg von entzündungsfördernden Lymphozyten; dabei sinkt die Zahl der Lymphozyten im Blut. In Studien traten Magen-Darm-Beschwerden seltener auf als mit Dimethylfumarat.","nebenwirkungen":{"sehrHaeufig":["Flush (Gesichtsrötung mit Wärmegefühl)","Durchfall, Übelkeit, Bauchschmerzen","Ketonkörper im Urin (Laborbefund)"],"haeufig":["Lymphopenie und Leukopenie (Mangel an weissen Blutkörperchen)","Erbrechen, Dyspepsie (Verdauungsbeschwerden), Gastritis","Magen-Darm-Infekt (Gastroenteritis)","Hitzewallungen, Hitzegefühl, Brennen der Haut","Juckreiz, Ausschlag, Hautrötung","Proteinurie (Eiweiss im Urin)","Erhöhte Leberwerte"],"gelegentlich":["Überempfindlichkeitsreaktionen","Thrombozytopenie (Mangel an Blutplättchen)"],"selten":["Arzneimittelbedingte Leberschädigung"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Herpes zoster (Gürtelrose)","Anaphylaxie, Angioödem","Fliessschnupfen"]},"schwangerschaft":"Nur wenige Erfahrungen; während der Schwangerschaft nur anwenden, wenn unbedingt nötig.","stillzeit":"Ein Risiko für das Kind ist nicht auszuschliessen; es muss entschieden werden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Kapseln ganz schlucken, nicht zerdrücken oder kauen. Die Einnahme mit einer Mahlzeit kann Flush und Magen-Darm-Beschwerden mildern.","Blutbild (Lymphozyten), Leber- und Nierenwerte vor Beginn und regelmässig während der Behandlung kontrollieren lassen.","Neue oder zunehmende Schwäche, Seh-, Sprach- oder Denkstörungen sofort melden (Verdacht auf PML).","Gesichtsrötung und Wärmegefühl zu Beginn sind häufig und meist harmlos; sie nehmen mit der Zeit ab."],"darreichung":["Magensaftresistente Hartkapseln"]},"distickstoffmonoxid":{"wirkmechanismus":"Lindert Schmerzen und wirkt beruhigend, solange es eingeatmet wird; nach Ende der Inhalation klingt die Wirkung innert Minuten ab. Distickstoffmonoxid hemmt NMDA-Rezeptoren im Zentralnervensystem und setzt körpereigene Opioide frei, die schmerzhemmende Nervenbahnen aktivieren. Allein ist es nur ein schwaches Narkosemittel. Es oxidiert das Kobalt im Vitamin B12 und hemmt so die Methioninsynthase; bei langer oder wiederholter Anwendung kann dies Blutbildung und Nerven schädigen.","nebenwirkungen":{"haeufig":["Schwindel, Benommenheit","Euphorie (Hochgefühl)","Übelkeit, Erbrechen"],"unbekannt":["Megaloblastäre Anämie und Leukopenie bei längerer oder wiederholter Anwendung","Nervenschäden (Polyneuropathie, Rückenmarksdegeneration) bei längerer Anwendung oder Missbrauch","Kopfschmerzen","Krampfanfälle","Verwirrtheit, Angst, Unruhe, Psychose","Abhängigkeit","Ohrenschmerzen und Druckgefühl im Mittelohr","Geblähter Darm"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; die kurzzeitige Anwendung, z. B. zur Schmerzlinderung unter der Geburt, ist üblich. Längere oder wiederholte Anwendung vermeiden.","stillzeit":"Kurzzeitige Anwendung ist mit dem Stillen vereinbar; nicht während des Stillens selbst einatmen.","hinweise":["Wird nur unter Aufsicht von geschultem Fachpersonal über Maske oder Mundstück eingeatmet.","Nach der Anwendung erst dann ein Fahrzeug lenken oder Maschinen bedienen, wenn die Wirkung vollständig abgeklungen ist und die Fachperson es erlaubt.","Missbrauch als Partydroge kann schwere, teils bleibende Nervenschäden verursachen."],"darreichung":["Gas zur medizinischen Anwendung (Inhalation)","Gasgemisch mit 50 % Sauerstoff"]},"disulfiram":{"wirkmechanismus":"Macht Alkohol unverträglich: Schon kleine Mengen führen zu Hautrötung, Herzrasen, Übelkeit und Atemnot. Disulfiram hemmt irreversibel das Enzym Aldehyddehydrogenase, sodass sich beim Alkoholabbau das giftige Acetaldehyd im Blut anhäuft (Disulfiram-Alkohol-Reaktion). Die Abschreckung soll die Abstinenz unterstützen. Weil das Enzym erst neu gebildet werden muss, hält die Wirkung bis zu 2 Wochen nach der letzten Einnahme an.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit","Mundgeruch, metallischer oder knoblauchartiger Geschmack","Übelkeit, Erbrechen, Magen-Darm-Beschwerden","Verminderte Libido","Allergische Hautreaktionen","Psychotische Reaktionen, Depression","Periphere Neuropathie (Nervenschäden) und Sehnerventzündung","Hepatitis bis zum Leberversagen"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung nicht empfohlen.","stillzeit":"Nicht anwenden.","hinweise":["Erst beginnen, wenn mindestens 24 Stunden kein Alkohol getrunken wurde; die Alkoholunverträglichkeit hält bis zu 2 Wochen nach der letzten Einnahme an.","Versteckten Alkohol meiden: Hustensäfte, Tropfen, Mundwasser, Saucen, Desserts sowie alkoholhaltige Kosmetika und Rasierwasser.","Leberwerte vor und während der Behandlung kontrollieren lassen; bei Gelbsucht, starker Müdigkeit oder Appetitlosigkeit sofort ärztlich melden.","Einen Ausweis über die Disulfiram-Behandlung mit sich tragen."],"darreichung":["Brausetabletten"]},"dobutamin":{"wirkmechanismus":"Stärkt die Pumpkraft des Herzens. Dobutamin ist ein synthetisches Katecholamin, das vorwiegend die Beta-1-Rezeptoren des Herzmuskels stimuliert und so Schlagkraft und Herzzeitvolumen erhöht. Herzfrequenz und Blutdruck steigen meist nur mässig, weil sich schwache gefässerweiternde (Beta-2) und gefässverengende (Alpha-1) Effekte weitgehend aufheben. Anders als Dopamin setzt es kein Noradrenalin frei; die Wirkung klingt wenige Minuten nach Infusionsende ab.","nebenwirkungen":{"unbekannt":["Herzrasen (Tachykardie), Extrasystolen, Herzklopfen","Herzrhythmusstörungen bis Kammertachykardie oder Kammerflimmern","Blutdruckanstieg, seltener Blutdruckabfall","Brustschmerzen (Angina pectoris)","Kopfschmerzen, Übelkeit","Atemnot","Hypokaliämie (Kaliummangel)","Venenentzündung an der Infusionsstelle"]},"schwangerschaft":"Keine ausreichenden Daten; nur bei klarer Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Nicht bekannt, ob Dobutamin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital als Dauerinfusion mit Infusionspumpe unter laufender Überwachung von EKG, Blutdruck und Puls gegeben.","Nicht mit alkalischen Lösungen (z. B. Natriumhydrogencarbonat) in derselben Leitung mischen."],"darreichung":["Infusionskonzentrat bzw. Infusionslösung"]},"docetaxel":{"wirkmechanismus":"Hemmt die Zellteilung, indem es das Zellskelett der Krebszellen erstarren lässt. Docetaxel fördert den Zusammenbau von Tubulin zu Mikrotubuli und hemmt deren Abbau; mit den starren Mikrotubuli kann keine funktionsfähige Mitosespindel entstehen. Die Zellen werden in der Mitose blockiert und sterben ab. Docetaxel wird in der Leber hauptsächlich über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Anämie, febrile Neutropenie, Infektionen","Überempfindlichkeitsreaktionen","Periphere sensorische Neuropathie (Kribbeln, Taubheit), Geschmacksstörungen","Atemnot","Stomatitis, Durchfall, Übelkeit, Erbrechen, Appetitlosigkeit","Haarausfall, Hautreaktionen, Nagelveränderungen","Flüssigkeitseinlagerung (Ödeme)","Muskelschmerzen, Schwäche (Asthenie), Schmerzen"],"haeufig":["Thrombozytopenie, Blutungen","Motorische Neuropathie (Muskelschwäche)","Herzrhythmusstörungen","Blutdruckabfall oder -anstieg","Verstopfung, Bauchschmerzen, Magen-Darm-Blutungen","Gelenkschmerzen","Erhöhte Leberwerte und Bilirubin","Reaktionen an der Infusionsstelle"],"gelegentlich":["Herzschwäche","Ösophagitis (Speiseröhrenentzündung)"],"unbekannt":["Anaphylaktischer Schock","Interstitielle Lungenerkrankung, Pneumonitis, Lungenfibrose","Neutropenische Enterokolitis, ischämische Kolitis, Darmperforation","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Sklerodermie-artige Hautveränderungen","Zystoides Makulaödem (Sehstörung), vermehrter Tränenfluss","Hyponatriämie (Natriummangel), Tumorlyse-Syndrom","Akute myeloische Leukämie, myelodysplastisches Syndrom (Zweiterkrankung)","Strahlen-Recall-Reaktionen"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Vor jeder Infusion wird ein Kortikosteroid (z. B. Dexamethason) eingenommen, um Flüssigkeitseinlagerungen und Überempfindlichkeitsreaktionen zu vermindern.","Die Infusionslösung enthält Alkohol: nach der Infusion Fahrtüchtigkeit beachten.","Blutbild vor jedem Zyklus; bei Fieber, Bauchschmerzen oder Durchfall sofort ärztliche Hilfe holen.","Gewichtszunahme, Schwellungen oder Atemnot melden (Flüssigkeitseinlagerung)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"dolutegravir":{"wirkmechanismus":"Verhindert, dass HIV sein Erbgut in die menschlichen Zellen einbaut. Dolutegravir bindet an das aktive Zentrum der viralen Integrase und blockiert den Strangtransfer, mit dem die virale DNA in die DNA der Wirtszelle eingefügt wird; ohne diesen Schritt kann sich das Virus nicht vermehren. Dolutegravir hat eine hohe Resistenzbarriere. Es hemmt zudem den Nierentransporter OCT2, was den Kreatininwert leicht erhöht, ohne die Nierenfunktion zu verschlechtern.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall"],"haeufig":["Schlaflosigkeit, abnorme Träume","Depression, Angst","Schwindel, Schläfrigkeit","Erbrechen, Blähungen, Bauchschmerzen","Hautausschlag, Juckreiz","Müdigkeit","Erhöhte Leberwerte und Kreatinkinase (CK)","Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen (Ausschlag, Fieber, Organbeteiligung)","Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch (vor allem bei Depression in der Vorgeschichte)","Panikattacken","Gelenk- und Muskelschmerzen","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen","Erhöhtes Bilirubin","Suizid (bei psychischer Vorerkrankung)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit in der Schwangerschaft angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte bei Einnahme zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Magnesium-, Eisen-, Calcium- oder Zinkpräparate und Multivitamine nur zeitversetzt (Dolutegravir 2 Stunden davor oder 6 Stunden danach).","Bei Hautausschlag mit Fieber, Blasen, Gelenkschmerzen oder Gelbsucht sofort ärztlich melden.","Ein leicht erhöhter Kreatininwert zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"dolutegravir-lamivudin":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Dolutegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Lamivudin, ein Cytidin-Analogon, wird in den Zellen zum Triphosphat aktiviert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führt zum Kettenabbruch. Dank der hohen Resistenzbarriere von Dolutegravir genügen bei geeigneten Personen zwei Wirkstoffe.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Schläfrigkeit","Übelkeit, Durchfall, Erbrechen, Blähungen, Bauchschmerzen","Schlaflosigkeit, abnorme Träume","Depression, Angst","Hautausschlag, Juckreiz, Haarausfall","Gelenk- und Muskelbeschwerden","Müdigkeit","Erhöhte Leberwerte und Kreatinkinase (CK), Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen","Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch, Panikattacken (vor allem bei psychischer Vorerkrankung)","Neutropenie, Anämie, Thrombozytopenie","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Rhabdomyolyse (Muskelzerfall)","Angioödem (Schwellung von Haut und Schleimhäuten)","Suizid (bei psychischer Vorerkrankung)"],"sehrSelten":["Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Erythroblastopenie (Aplasie der roten Blutzellen)","Laktatazidose (Übersäuerung des Blutes)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte durch Dolutegravir zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Magnesium-, Eisen-, Calcium- oder Zinkpräparate und Multivitamine nur zeitversetzt (Dovato 2 Stunden davor oder 6 Stunden danach).","Vor Beginn auf Hepatitis B testen; bei Hepatitis B nicht eigenmächtig absetzen.","Ein leicht erhöhter Kreatininwert zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"dolutegravir-rilpivirin":{"wirkmechanismus":"Zwei Wirkstoffe blockieren das HI-Virus an verschiedenen Stellen. Dolutegravir hemmt die Integrase und verhindert den Einbau des Virus-Erbguts in die Wirtszelle. Rilpivirin (NNRTI) bindet direkt an die Reverse Transkriptase und blockiert das Umschreiben der Virus-RNA in DNA. Dolutegravir hemmt zudem die Nieren-Transporter OCT2 und MATE1; dadurch steigt das Kreatinin leicht an, ohne dass die Nierenfunktion abnimmt, und die Ausscheidung von Metformin wird vermindert.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Durchfall, Übelkeit, Bauchschmerzen, Blähungen, Erbrechen","Depression, Angst, Schlaflosigkeit, abnorme Träume","Hautausschlag, Juckreiz","Müdigkeit","Gewichtszunahme","Erhöhte Leberwerte, Kreatinkinase, Blutfette und Pankreas-Enzyme"],"gelegentlich":["Suizidgedanken, Suizidversuch (v. a. bei psychischer Vorerkrankung)","Überempfindlichkeitsreaktionen","Hepatitis","Gelenk- und Muskelschmerzen","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung anwenden; die Rilpivirin-Spiegel sind in der Schwangerschaft tiefer (Viruslast eng kontrollieren). Die Behandlung soll mit einem HIV-Zentrum geplant werden.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Keine Protonenpumpenhemmer (z. B. Omeprazol, Pantoprazol); Antazida, H2-Blocker und Mineralstoffpräparate nur mit dem vorgeschriebenen Zeitabstand.","Bei Hautausschlag mit Fieber, Blasen, Schleimhautbeteiligung oder Unwohlsein sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"domperidon":{"wirkmechanismus":"Wirkt gegen Übelkeit und beschleunigt die Weitergabe des Mageninhalts in den Darm. Domperidon blockiert Dopamin-D2-Rezeptoren in der Brechreizzone (Chemorezeptor-Triggerzone), die ausserhalb der Blut-Hirn-Schranke liegt, sowie im Magen. Dadurch steigen Magenbeweglichkeit und Druck des unteren Speiseröhren-Schliessmuskels. Da es kaum ins Gehirn gelangt, sind Bewegungsstörungen seltener als bei Metoclopramid; über die Hypophyse kann es jedoch das Prolaktin erhöhen. In höheren Spiegeln hemmt es Kaliumkanäle im Herzen (hERG) und verlängert die QT-Zeit.","nebenwirkungen":{"haeufig":["Mundtrockenheit"],"gelegentlich":["Kopfschmerzen, Schläfrigkeit","Angst, Libidoverlust","Durchfall","Hautausschlag, Juckreiz","Milchfluss aus der Brust (Galaktorrhö), Brustschmerzen und -spannen","Schwächegefühl (Asthenie)"],"unbekannt":["Ventrikuläre Herzrhythmusstörungen, QT-Verlängerung, Torsade de pointes, plötzlicher Herztod","Krampfanfälle, extrapyramidale Bewegungsstörungen, Blickkrämpfe","Unruhe, Nervosität","Anaphylaxie, Angioödem, Nesselsucht","Brustvergrösserung beim Mann (Gynäkomastie), Ausbleiben der Regelblutung","Harnverhalt","Erhöhte Leberwerte und erhöhtes Prolaktin im Blut"]},"schwangerschaft":"Nur begrenzte Erfahrungen; in der Schwangerschaft nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; ein Risiko für Herznebenwirkungen beim Säugling ist nicht ausgeschlossen. Nur nach ärztlicher Abwägung.","hinweise":["Höchstdosis 30 mg pro Tag; in der Regel nicht länger als eine Woche anwenden.","Vor den Mahlzeiten einnehmen; Schmelztabletten auf der Zunge zergehen lassen.","Alle anderen Medikamente angeben – viele erhöhen zusammen mit Domperidon das Risiko für Herzrhythmusstörungen.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Schmelztabletten"]},"donanemab":{"wirkmechanismus":"Hilft dem Immunsystem, schädliche Eiweissablagerungen (Amyloid-Plaques) aus dem Gehirn zu entfernen, und verlangsamt so das Fortschreiten der frühen Alzheimer-Krankheit. Donanemab ist ein humanisierter monoklonaler IgG1-Antikörper gegen eine verkürzte, Pyroglutamat-modifizierte Form von Amyloid-beta (N3pG), die nur in bestehenden Plaques vorkommt. Die Bindung führt zum Abbau der Plaques durch Fresszellen des Gehirns (Mikroglia). Sind die Plaques weitgehend entfernt, kann die Behandlung beendet werden.","nebenwirkungen":{"sehrHaeufig":["ARIA-E: amyloidbedingte Hirnschwellung (Ödem), oft ohne Beschwerden","ARIA-H: Mikroblutungen und Eisenablagerungen (Siderose) im Gehirn","Kopfschmerzen"],"haeufig":["Infusionsreaktionen (Frösteln, Hautrötung, Übelkeit, Atemnot, Blutdruckveränderungen)"],"gelegentlich":["Hirnblutung über 1 cm","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Schwere ARIA mit Verwirrtheit, Sehstörungen, Krampfanfällen oder Bewusstseinsstörung"]},"schwangerschaft":"Keine Erfahrungen; Antikörper können die Plazenta passieren – Anwendung nicht empfohlen.","stillzeit":"Keine Daten; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Regelmässige MRI-Kontrollen sind fester Bestandteil der Behandlung.","Bei Kopfschmerzen, Verwirrtheit, Sehstörungen, Schwindel, Übelkeit oder Krampfanfällen sofort ärztliche Hilfe holen.","Bei jedem Spital- oder Notfallkontakt angeben, dass Donanemab gegeben wird – wichtig vor Blutverdünnern oder einer Thrombolyse.","Die Infusion erfolgt alle 4 Wochen; die Behandlung kann beendet werden, wenn die Amyloid-Plaques weitgehend entfernt sind."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"donepezil":{"wirkmechanismus":"Verbessert bei Alzheimer-Demenz vorübergehend Gedächtnis und Alltagsfähigkeiten, indem es den Abbau des Botenstoffs Acetylcholin im Gehirn bremst. Donepezil hemmt spezifisch und reversibel die Acetylcholinesterase und erhöht so die Acetylcholin-Konzentration an den Synapsen der noch funktionierenden Nervenzellen. Den Verlauf der Erkrankung hält es nicht auf. Es wird über CYP3A4 und CYP2D6 abgebaut und hat eine sehr lange Halbwertszeit (etwa 70 Stunden).","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Kopfschmerzen"],"haeufig":["Appetitlosigkeit","Erbrechen, Bauchbeschwerden","Halluzinationen, Unruhe, Aggressivität, abnorme Träume","Schwindel, Schlaflosigkeit, Ohnmacht (Synkope)","Muskelkrämpfe","Harninkontinenz","Müdigkeit, Schmerzen, Stürze","Hautausschlag, Juckreiz, Erkältung"],"gelegentlich":["Bradykardie (langsamer Puls)","Krampfanfälle","Magen-Darm-Blutungen, Magen- und Zwölffingerdarmgeschwüre","Vermehrter Speichelfluss","Leichter Anstieg der Kreatinkinase (CK)"],"selten":["Sinuatrialer Block, AV-Block (Reizleitungsstörungen)","Extrapyramidale Symptome (Bewegungsstörungen)","Leberfunktionsstörungen, Hepatitis"],"sehrSelten":["Malignes neuroleptisches Syndrom","Rhabdomyolyse (Muskelzerfall)"],"unbekannt":["QT-Verlängerung, Torsade de pointes","Pisa-Syndrom (seitliche Rumpfneigung)","Gesteigerte Libido, Hypersexualität"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht bekannt, ob Donepezil in die Muttermilch übergeht; nicht stillen.","hinweise":["Abends vor dem Schlafengehen einnehmen; Schmelztabletten auf der Zunge zergehen lassen.","Vor einer Narkose die Einnahme angeben.","Bei Schwindel, Ohnmacht oder sehr langsamem Puls ärztlich abklären lassen.","Die Fahrtüchtigkeit kann durch die Demenz und durch Nebenwirkungen eingeschränkt sein."],"darreichung":["Filmtabletten","Schmelztabletten"]},"dopamin":{"wirkmechanismus":"Stärkt die Pumpkraft des Herzens und erhöht je nach Dosis den Blutdruck. Dopamin ist ein körpereigenes Katecholamin und die Vorstufe von Noradrenalin. In niedriger Dosis stimuliert es vor allem Dopamin-D1-Rezeptoren (Gefässerweiterung in Niere und Bauchorganen), in mittlerer Dosis Beta-1-Rezeptoren des Herzens (mehr Schlagkraft und Herzfrequenz) und in hoher Dosis Alpha-1-Rezeptoren (Gefässverengung, Blutdruckanstieg). Zusätzlich setzt es Noradrenalin aus Nervenendigungen frei.","nebenwirkungen":{"unbekannt":["Herzrasen (Tachykardie), Extrasystolen, Herzklopfen","Herzrhythmusstörungen bis Kammertachykardie","Brustschmerzen (Angina pectoris)","Blutdruckanstieg oder Blutdruckabfall","Kopfschmerzen, Übelkeit, Erbrechen","Atemnot (Dyspnoe)","Gefässverengung mit kalten Fingern und Zehen bis Gewebsuntergang (Gangrän)","Gewebsnekrose bei Austritt der Infusion ins Gewebe"]},"schwangerschaft":"Keine ausreichenden Daten; nur bei lebensbedrohlichen Zuständen nach sorgfältiger Abwägung (mögliche Minderdurchblutung der Gebärmutter).","stillzeit":"Nicht bekannt, ob Dopamin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital (Intensivstation, Notfall, Anästhesie) als Dauerinfusion mit Infusionspumpe unter laufender Überwachung von Blutdruck, Puls und EKG gegeben.","Nicht abrupt beenden, sondern schrittweise reduzieren (Gefahr eines Blutdruckabfalls).","Schmerzen, Blässe oder Schwellung an der Infusionsstelle sofort dem Pflegepersonal melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"doravirin":{"wirkmechanismus":"Hemmt die Vermehrung des HI-Virus, indem es ein Schlüsselenzym des Virus blockiert. Doravirin bindet nicht-kompetitiv an die Reverse Transkriptase von HIV-1 und verhindert so das Umschreiben der viralen RNA in DNA. Es wird über CYP3A4 abgebaut, hemmt oder induziert dieses Enzym selbst aber nicht in relevantem Ausmass. Gegen HIV-2 wirkt es nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Schläfrigkeit","Abnorme Träume, Schlaflosigkeit","Übelkeit, Durchfall, Bauchschmerzen, Blähungen, Erbrechen","Hautausschlag","Müdigkeit","Anstieg des Leberwerts ALT"],"gelegentlich":["Albträume, Depression, Angst, Reizbarkeit, Verwirrtheit","Suizidgedanken","Konzentrations- und Gedächtnisstörungen, Kribbeln","Bluthochdruck","Verstopfung, Verdauungsbeschwerden","Juckreiz, Muskel- und Gelenkschmerzen","Erhöhte Lipase und Amylase (Bauchspeicheldrüsenenzyme), tiefes Phosphat im Blut"],"selten":["Aggression, Halluzinationen","Akute Nierenschädigung, Nierensteine","Allergische Hautentzündung","Atemnot"]},"schwangerschaft":"Begrenzte Erfahrungen; vorsichtshalber soll die Anwendung in der Schwangerschaft vermieden werden. Die Behandlung ist mit einem HIV-Zentrum zu planen.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen.","Johanniskraut ist verboten; vor neuen Medikamenten (z. B. Antiepileptika, Tuberkulosemittel) Wechselwirkungen prüfen lassen.","Regelmässig und ohne Unterbruch einnehmen – vergessene Dosen begünstigen Resistenzen."],"darreichung":["Filmtabletten"]},"doravirin-lamivudin-tenofovirdisoproxil":{"wirkmechanismus":"Drei Wirkstoffe hemmen die Reverse Transkriptase des HI-Virus auf zwei Arten. Doravirin (NNRTI) bindet direkt an das Enzym und blockiert das Umschreiben der Virus-RNA in DNA. Lamivudin (ein Cytidin-Analogon) und Tenofovir (aus dem Prodrug Tenofovirdisoproxil) werden in den Zellen aktiviert und führen nach Einbau in die Virus-DNA zum Kettenabbruch. Lamivudin und Tenofovir wirken auch gegen Hepatitis B.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Schläfrigkeit","Abnorme Träume, Schlaflosigkeit","Übelkeit, Durchfall, Bauchschmerzen, Erbrechen, Blähungen","Husten","Haarausfall, Hautausschlag","Müdigkeit, Fieber","Anstieg des Leberwerts ALT"],"gelegentlich":["Neutropenie, Anämie, Thrombozytopenie","Albträume, Depression, Angst, Verwirrtheit, Suizidgedanken","Tiefes Phosphat oder Kalium im Blut","Verstopfung, Verdauungsbeschwerden","Muskel- und Gelenkschmerzen, Muskelschwäche","Kreatininanstieg, erhöhte Lipase und Amylase","Bluthochdruck, Juckreiz"],"selten":["Laktatazidose (Übersäuerung des Blutes)","Akute Nierenschädigung, proximale Tubulopathie (Fanconi-Syndrom), Nierensteine","Osteomalazie (Knochenerweichung)","Pankreatitis, Hepatitis, Fettleber","Rhabdomyolyse (Muskelzerfall)","Aggression, Halluzinationen"],"sehrSelten":["Erythroblastopenie (Ausfall der Bildung roter Blutkörperchen)"]},"schwangerschaft":"Begrenzte Erfahrungen mit Doravirin; vorsichtshalber soll die Anwendung in der Schwangerschaft vermieden werden. Die Behandlung ist mit einem HIV-Zentrum zu planen.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen.","Nierenfunktion und Phosphat werden regelmässig kontrolliert; Schmerzmittel wie Ibuprofen oder Diclofenac nicht über längere Zeit ohne Rücksprache einnehmen.","Bei Hepatitis B nicht eigenmächtig absetzen (Gefahr eines schweren Hepatitis-Schubs); kein Johanniskraut."],"darreichung":["Filmtabletten"]},"dornase-alfa":{"wirkmechanismus":"Verflüssigt den zähen Schleim in den Atemwegen bei zystischer Fibrose. Dieser Schleim enthält grosse Mengen DNA aus zerfallenen weissen Blutkörperchen, die ihn besonders zäh machen. Dornase alfa ist eine gentechnisch hergestellte Form des menschlichen Enzyms Desoxyribonuklease I und spaltet diese DNA ausserhalb der Zellen. Dadurch sinkt die Zähigkeit des Auswurfs, er lässt sich leichter abhusten, und die Lungenfunktion verbessert sich.","nebenwirkungen":{"selten":["Bindehautentzündung (Konjunktivitis)","Stimmveränderung, Heiserkeit (Dysphonie)","Atemnot (Dyspnoe)","Rachen- und Kehlkopfentzündung, Schnupfen","Verdauungsbeschwerden (Dyspepsie)","Hautausschlag, Nesselsucht","Brustschmerzen, Fieber","Vorübergehende Abnahme der Lungenfunktionswerte"]},"schwangerschaft":"Nur begrenzte Erfahrungen; die Aufnahme in den Körper ist sehr gering. Anwendung nach ärztlicher Abwägung.","stillzeit":"Übergang in die Muttermilch nicht bekannt, wegen der sehr geringen Aufnahme in den Körper aber unwahrscheinlich; Anwendung nach ärztlicher Abwägung.","hinweise":["Nur mit einem geeigneten Düsenvernebler inhalieren; nicht mit anderen Arzneimitteln im Vernebler mischen oder verdünnen.","Ampullen im Kühlschrank und lichtgeschützt aufbewahren.","Atemphysiotherapie und die übrige Behandlung der zystischen Fibrose wie gewohnt fortsetzen."],"darreichung":["Lösung für einen Vernebler"]},"dorzolamid":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Dorzolamid hemmt das Enzym Carboanhydrase II im Ziliarkörper des Auges; dadurch entsteht weniger Bicarbonat, und der damit verbundene Natrium- und Flüssigkeitstransport ins Auge nimmt ab. Als Augentropfen wirkt es vor allem am Auge, während die Wirkung auf den übrigen Körper gering bleibt. Chemisch ist Dorzolamid ein Sulfonamid.","nebenwirkungen":{"sehrHaeufig":["Brennen und Stechen am Auge"],"haeufig":["Oberflächliche Hornhautentzündung (Keratitis punctata)","Tränenfluss, Bindehautentzündung, Lidentzündung, Augenjucken","Verschwommenes Sehen","Bitterer Geschmack","Kopfschmerzen, Übelkeit, Müdigkeit"],"gelegentlich":["Entzündung von Regenbogenhaut und Ziliarkörper (Iridozyklitis)"],"selten":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Bronchospasmus)","Schwindel, Kribbeln (Parästhesien)","Augenrötung, Augenschmerzen, Lidkrusten, vorübergehende Kurzsichtigkeit","Hornhautschwellung, Aderhautabhebung nach Glaukomoperation","Nasenbluten, Rachenreizung, Mundtrockenheit","Nierensteine","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"],"unbekannt":["Fremdkörpergefühl im Auge"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Dorzolamid in die Muttermilch übergeht; ist die Behandlung nötig, wird das Stillen nicht empfohlen.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen oder den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei mehreren Augentropfen mindestens 10 Minuten Abstand halten.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen."],"darreichung":["Augentropfen"]},"dorzolamid-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck, indem die Bildung von Kammerwasser auf zwei Wegen gedrosselt wird. Dorzolamid hemmt die Carboanhydrase II im Ziliarkörper und vermindert so die Bicarbonat- und Flüssigkeitsbildung. Timolol, ein nicht selektiver Betablocker, verringert die Kammerwasserproduktion zusätzlich. Ein Teil beider Wirkstoffe gelangt in den Kreislauf; vor allem Timolol kann Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Brennen und Stechen am Auge","Geschmacksstörung (bitterer Geschmack)"],"haeufig":["Augenrötung, Augenjucken, Tränenfluss","Verschwommenes Sehen","Hornhauterosion, oberflächliche Hornhautentzündung","Bindehaut- und Lidentzündung, Lidreizung","Kopfschmerzen, Übelkeit, Müdigkeit","Nasennebenhöhlenentzündung (Sinusitis)"],"gelegentlich":["Entzündung von Regenbogenhaut und Ziliarkörper (Iridozyklitis)","Schwindel"],"selten":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Bronchospasmus)","Aderhautabhebung nach Glaukomoperation, Doppelbilder, hängendes Augenlid","Kribbeln (Parästhesien), Schlaflosigkeit, Albträume","Nierensteine","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"],"unbekannt":["Langsamer Puls (Bradykardie), AV-Block, Herzinsuffizienz, Blutdruckabfall","Verdeckte Unterzuckerung"]},"schwangerschaft":"In der Schwangerschaft nicht anwenden (Dorzolamid im Tierversuch fruchtschädigend; Timolol kann beim Neugeborenen Puls und Blutzucker senken).","stillzeit":"Nicht anwenden; ist die Behandlung nötig, wird abgestillt.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 10 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"dostarlimab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, damit Abwehrzellen Krebszellen wieder bekämpfen. Dostarlimab ist ein humanisierter IgG4-Antikörper, der an den Rezeptor PD-1 auf T-Zellen bindet und dessen Aktivierung durch die Liganden PD-L1 und PD-L2 blockiert. Tumoren mit Mismatch-Reparatur-Defizienz tragen besonders viele Mutationen und sind deshalb für das Immunsystem gut erkennbar; sie sprechen besonders gut auf die Behandlung an.","nebenwirkungen":{"sehrHaeufig":["Anämie (Blutarmut)","Durchfall, Übelkeit, Erbrechen","Hautausschlag, Juckreiz","Erhöhte Leberwerte","Müdigkeit"],"haeufig":["Hypothyreose, Hyperthyreose (Schilddrüsenunter- und -überfunktion)","Nebenniereninsuffizienz","Pneumonitis (nicht-infektiöse Lungenentzündung)","Kolitis (Dickdarmentzündung)","Hepatitis (Leberentzündung)","Infusionsreaktionen","Fieber","Gelenk- und Muskelschmerzen"],"gelegentlich":["Typ-1-Diabetes","Hypophysitis, Thyreoiditis","Nephritis (Nierenentzündung)","Myositis, Arthritis"],"unbekannt":["Myokarditis (Herzmuskelentzündung)","Myasthenia gravis, Guillain-Barré-Syndrom, Enzephalitis","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht empfohlen: IgG-Antikörper gehen über die Plazenta, und die PD-1-Blockade kann die Toleranz gegenüber dem Ungeborenen stören. Frauen im gebärfähigen Alter verhüten während der Behandlung und 4 Monate danach.","stillzeit":"Während der Behandlung und 4 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch Monate nach Therapieende.","Den Patientenausweis immer bei sich tragen und allen Ärztinnen und Ärzten zeigen.","Leber-, Nieren- und Schilddrüsenwerte sowie Blutzucker werden regelmässig kontrolliert.","Kortison nicht eigenmächtig beginnen oder absetzen."],"darreichung":["Infusionskonzentrat"]},"doxazosin":{"wirkmechanismus":"Entspannt die Muskulatur in den Blutgefässen sowie in Prostata und Blasenhals. Doxazosin blockiert selektiv und kompetitiv Alpha-1-Rezeptoren, über die Noradrenalin normalerweise die glatte Muskulatur zusammenzieht. In den Gefässen sinkt dadurch der Widerstand und damit der Blutdruck; in Prostata und Blasenhals lässt der Druck auf die Harnröhre nach, sodass der Urin leichter abfliesst. Die erste Dosis kann einen deutlichen Blutdruckabfall auslösen (First-Dose-Effekt).","nebenwirkungen":{"haeufig":["Schwindel, Drehschwindel, Kopfschmerzen, Schläfrigkeit","Blutdruckabfall, auch beim Aufstehen (orthostatische Hypotonie)","Herzklopfen, Herzrasen","Atemwegsinfekte, Schnupfen, Husten, Atemnot","Bauchschmerzen, Verdauungsbeschwerden, Übelkeit, Mundtrockenheit","Harnwegsinfekt, Blasenentzündung, Harninkontinenz","Schwäche, grippeähnliche Beschwerden, Brustschmerzen, Wassereinlagerungen in den Beinen","Rücken- und Muskelschmerzen, Juckreiz"],"gelegentlich":["Ohnmacht (Synkope), Zittern","Angina pectoris, Herzinfarkt","Schlaganfall","Angst, Depression, Schlaflosigkeit","Verstopfung, Durchfall, Erbrechen, Blähungen","Nasenbluten","Erhöhte Leberwerte","Gewichtszunahme, Gicht","Erektionsstörungen"],"selten":["Magen-Darm-Verschluss (Retardtabletten)"],"sehrSelten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Bradykardie, Herzrhythmusstörungen","Bronchospasmus","Leberentzündung, Cholestase (Gallenstau), Gelbsucht","Priapismus (schmerzhafte Dauererektion)","Verschwommenes Sehen, Haarausfall, Nesselsucht"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Kataraktoperation","Retrograde Ejakulation (Samenerguss in die Blase)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; es gibt kaum Erfahrungen bei Schwangeren.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Die erste Dosis kann starken Schwindel oder eine Ohnmacht auslösen – Behandlung mit niedriger Dosis beginnen, zu Beginn kein Auto fahren und langsam aufstehen.","Vor einer Operation am grauen Star die Augenärztin oder den Augenarzt über die Einnahme informieren.","Retardtabletten ganz schlucken, nicht teilen oder kauen; die leere Tablettenhülle kann im Stuhl erscheinen.","Bei einer schmerzhaften Dauererektion sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Retardtabletten"]},"doxepin":{"wirkmechanismus":"Wirkt stimmungsaufhellend, angstlösend und stark beruhigend. Doxepin hemmt die Wiederaufnahme von Noradrenalin und Serotonin in die Nervenendigungen; sein Abbaustoff Desmethyldoxepin wirkt ebenfalls antidepressiv. Sehr ausgeprägt ist die Blockade von Histamin-H1-Rezeptoren (starke Müdigkeit), daneben werden Muskarin- und Alpha-1-Rezeptoren blockiert. Der Abbau erfolgt in der Leber vor allem über CYP2C19 und CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Benommenheit","Mundtrockenheit","Obstipation (Verstopfung)","Verschwommenes Sehen (Akkommodationsstörungen)","Schwindel, Blutdruckabfall beim Aufstehen","Vermehrtes Schwitzen","Zittern (Tremor)","Gewichtszunahme"],"haeufig":["Verstopfte Nase","Unruhe, Schlafstörungen, Kopfschmerzen","Herzrasen, Herzrhythmusstörungen","Blasenentleerungsstörungen","Libido- und Potenzstörungen","Durst","Hautausschlag, Juckreiz"],"unbekannt":["Krampfanfälle","Verwirrtheit, Delir (v. a. bei älteren Menschen)","QT-Verlängerung","Harnverhalt, Darmlähmung (paralytischer Ileus)","Blutbildveränderungen bis Agranulozytose","Erhöhte Leberwerte, Gelbsucht","Hyponatriämie (Natriummangel)","Suizidgedanken und suizidales Verhalten"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, besonders im 1. Drittel zurückhaltend. Bei Einnahme bis zur Geburt sind beim Neugeborenen Anpassungs- und Entzugsstörungen möglich.","stillzeit":"Kontraindiziert: Doxepin geht in die Muttermilch über, beim gestillten Säugling wurden Atemdämpfung und starke Schläfrigkeit beobachtet.","hinweise":["Wegen der dämpfenden Wirkung wird ein Grossteil der Tagesdosis meist abends eingenommen; Fahrtüchtigkeit eingeschränkt, keinen Alkohol trinken.","Die stimmungsaufhellende Wirkung setzt erst nach 2–4 Wochen ein; die beruhigende Wirkung schon früher.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung.","Eine Überdosis ist lebensgefährlich – für Kinder unzugänglich aufbewahren."],"darreichung":["Kapseln"]},"doxorubicin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen und verhindert so deren Teilung. Doxorubicin lagert sich zwischen die DNA-Basenpaare ein (Interkalation), hemmt die Topoisomerase II und führt zu DNA-Strangbrüchen; zudem entstehen freie Sauerstoffradikale. Die Radikalbildung im Herzmuskel gilt als Hauptursache der dosisabhängigen Herzschädigung. In pegylierten Liposomen verpackt (Caelyx) zirkuliert der Wirkstoff länger, reichert sich stärker im Tumorgewebe an und schädigt das Herz weniger.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Leukopenie, Neutropenie, Anämie, Thrombozytopenie","Infektionen","Haarausfall (bei konventionellem Doxorubicin meist vollständig)","Übelkeit, Erbrechen, Appetitlosigkeit","Mukositis, Stomatitis (Mund- und Schleimhautentzündung), Durchfall","Hand-Fuss-Syndrom (schmerzhafte Rötung von Handflächen und Fusssohlen, v. a. bei liposomalem Doxorubicin)","Fieber, Müdigkeit"],"haeufig":["Kardiomyopathie, Herzschwäche (dosisabhängig, auch Jahre später)","Herzrasen, Herzrhythmusstörungen","Bindehautentzündung (Konjunktivitis)","Juckreiz, Hautausschlag, Verfärbung von Haut und Nägeln","Lokale Reaktionen und Venenentzündung an der Injektionsstelle"],"unbekannt":["Akute myeloische Leukämie, myelodysplastisches Syndrom (Zweiterkrankung)","Anaphylaxie (schwere allergische Reaktion)","Thrombophlebitis, Thromboembolien","Gewebsnekrose bei Paravasat","Tumorlyse-Syndrom","Strahlen-Recall-Reaktion","Ausbleiben der Regelblutung, Unfruchtbarkeit"]},"schwangerschaft":"Fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – Doxorubicin geht in die Muttermilch über.","hinweise":["Der Urin kann sich 1–2 Tage nach der Gabe rötlich verfärben – das ist harmlos.","Herzfunktion vor Beginn und regelmässig kontrollieren; Atemnot, Herzklopfen oder geschwollene Beine melden – auch Jahre nach der Behandlung.","Konventionelles und liposomales Doxorubicin (Caelyx) sind nicht austauschbar.","Schmerzen oder Brennen an der Infusionsstelle sofort melden (Gefahr eines Paravasats)."],"darreichung":["Injektionslösung","Pulver zur Herstellung einer Injektionslösung","Liposomales Konzentrat zur Herstellung einer Infusionslösung"]},"doxycyclin":{"wirkmechanismus":"Hemmt das Wachstum und die Vermehrung von Bakterien. Doxycyclin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und verhindert die Anlagerung der Aminoacyl-tRNA; dadurch wird die Eiweissbildung der Bakterien blockiert (bakteriostatische Wirkung). Das Spektrum umfasst viele grampositive und gramnegative Keime sowie Erreger, die in Zellen leben, wie Chlamydien, Mykoplasmen und Rickettsien, ausserdem Borrelien. Doxycyclin ist gut fettlöslich, wird fast vollständig aufgenommen und reichert sich auch bei eingeschränkter Nierenfunktion kaum an.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Kopfschmerzen","Photosensibilität (sonnenbrandähnliche Hautreaktion bei Licht)","Hautausschlag","Überempfindlichkeitsreaktionen (z. B. Nesselsucht, Schwellungen, in schweren Fällen Anaphylaxie)"],"gelegentlich":["Dyspepsie (Sodbrennen, Magenschleimhautreizung)"],"selten":["Speiseröhrenentzündung und -geschwüre, Schluckbeschwerden","Durchfall, Bauchschmerzen, Zungenentzündung","Pseudomembranöse Kolitis (schwere Darmentzündung durch Clostridioides difficile)","Erhöhter Hirndruck (Pseudotumor cerebri) mit Kopfschmerzen und Sehstörungen","Leberentzündung, erhöhte Leberwerte","Blutbildveränderungen (hämolytische Anämie, Thrombozytopenie, Neutropenie)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Pankreatitis, Herzbeutelentzündung, Gelenk- und Muskelschmerzen, Ohrensausen"],"unbekannt":["Bleibende Zahnverfärbung und Zahnschmelzschäden bei Kindern unter 8 Jahren","Pilzinfektionen (Mund, Scheide)","Jarisch-Herxheimer-Reaktion (Fieber, Schüttelfrost) bei Borreliose oder Syphilis"]},"schwangerschaft":"Kontraindiziert: Doxycyclin kann beim ungeborenen Kind zu bleibender Zahnverfärbung und Störungen des Knochenwachstums führen, vor allem ab dem 4. Schwangerschaftsmonat.","stillzeit":"Kontraindiziert: geht in die Muttermilch über (Zahnverfärbung und Störung des Knochenwachstums beim Säugling möglich).","hinweise":["Mit einem grossen Glas Wasser in aufrechter Haltung einnehmen und danach mindestens 30 Minuten nicht hinlegen – nicht direkt vor dem Schlafengehen (Gefahr von Speiseröhrengeschwüren). Einnahme zu einer Mahlzeit verbessert die Magenverträglichkeit.","Calcium-, Magnesium-, Eisen- und Zinkpräparate sowie Antazida mit 2–3 Stunden Abstand einnehmen; grössere Mengen Milchprodukte nicht gleichzeitig.","Während der Behandlung und einige Tage danach starke Sonne und Solarium meiden, guten Sonnenschutz verwenden.","Bei starken Kopfschmerzen mit Sehstörungen oder bei schwerem, anhaltendem Durchfall sofort ärztlichen Rat einholen."],"darreichung":["Tabletten","Lösliche Tabletten"]},"dronedaron":{"wirkmechanismus":"Hilft, nach Vorhofflimmern den normalen Herzrhythmus zu halten, und bremst den Puls. Dronedaron ist ein mit Amiodaron verwandter Multikanalblocker ohne Jod: Es hemmt Kalium-, Natrium- und Calciumkanäle der Herzmuskelzellen und wirkt zusätzlich nicht kompetitiv antiadrenerg. Dadurch verlängern sich Aktionspotenzial und Refraktärzeit, und die Herzfrequenz sinkt. Es wird über CYP3A4 abgebaut und hemmt selbst CYP3A4, CYP2D6 und P-Glykoprotein.","nebenwirkungen":{"sehrHaeufig":["Erhöhtes Kreatinin im Blut","QT-Verlängerung im EKG","Neu auftretende oder verschlechterte Herzinsuffizienz"],"haeufig":["Bradykardie (langsamer Puls)","Durchfall, Erbrechen, Übelkeit, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Müdigkeit, Schwäche","Erhöhte Leberwerte"],"gelegentlich":["Interstitielle Lungenerkrankung (Pneumonitis, Lungenfibrose)","Geschmacksstörungen","Lichtempfindlichkeit der Haut, Ekzem, Hautrötung"],"selten":["Leberschäden bis zum lebensbedrohlichen akuten Leberversagen","Anaphylaxie und Angioödem","Geschmacksverlust","Gefässentzündung (Vaskulitis)"]},"schwangerschaft":"In Tierstudien fruchtschädigend; während der Schwangerschaft nicht empfohlen. Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Dronedaron in die Muttermilch übergeht (bei Tieren ja); entweder abstillen oder auf die Behandlung verzichten.","hinweise":["Zweimal täglich zum Frühstück und zum Abendessen einnehmen; keinen Grapefruitsaft trinken.","Regelmässige Kontrollen von EKG, Leber- und Nierenwerten.","Bei Zeichen einer Leberschädigung (Schmerzen im rechten Oberbauch, Gelbsucht, dunkler Urin) oder einer Herzschwäche (Atemnot, Gewichtszunahme, geschwollene Beine) sofort ärztliche Hilfe holen.","Vor jeder neuen Medikation Wechselwirkungen in der Apotheke prüfen lassen."],"darreichung":["Filmtabletten"]},"droperidol":{"wirkmechanismus":"Verhindert Übelkeit und Erbrechen, indem es Signale an das Brechzentrum im Gehirn blockiert. Droperidol ist ein Butyrophenon-Neuroleptikum und blockiert Dopamin-D2-Rezeptoren in der Chemorezeptor-Triggerzone (Area postrema). In den niedrigen Dosen gegen Übelkeit ist die beruhigende Wirkung gering; eine schwache Blockade von Alpha-1-Rezeptoren kann den Blutdruck senken. Wie andere Butyrophenone verlängert es die QT-Zeit.","nebenwirkungen":{"haeufig":["Schläfrigkeit"],"gelegentlich":["Angst, innere Unruhe, Akathisie (Sitzunruhe)","Dystonie (Muskelverkrampfungen), Blickkrämpfe","Tachykardie (Herzrasen), Schwindel","Hypotonie (Blutdruckabfall)"],"selten":["Verwirrtheit, Erregung","Extrapyramidale Störungen, Zittern, Krampfanfälle","Ventrikuläre Herzrhythmusstörungen","Anaphylaxie (schwere allergische Reaktion), Angioödem","Hautausschlag","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)"],"sehrSelten":["Blutbildveränderungen","Dysphorie (gedrückte, gereizte Stimmung)","QT-Verlängerung, Torsade de pointes, Herzstillstand","Plötzlicher Tod","Koma"],"unbekannt":["Halluzinationen","Inadäquate ADH-Sekretion mit Natriummangel","Bronchospasmus, Laryngospasmus (Verkrampfung der Atemwege)","Synkope (Ohnmacht)"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn klar notwendig. Nach Gabe gegen Ende der Schwangerschaft das Neugeborene auf Bewegungsstörungen und Unruhe überwachen.","stillzeit":"Geht in die Muttermilch über; eine einmalige Gabe ist vertretbar, wiederholte Gaben in der Stillzeit werden nicht empfohlen.","hinweise":["Wird nur im Spital verabreicht; bei Risikofaktoren werden Herzrhythmus und Sauerstoffsättigung überwacht.","Nach der Gabe mindestens 24 Stunden nicht Auto fahren, keine Maschinen bedienen und keinen Alkohol trinken."],"darreichung":["Injektionslösung"]},"drospirenon":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem es den Eisprung unterdrückt. Drospirenon ist ein vom Spironolacton abgeleitetes Gestagen: Es hemmt die Ausschüttung von LH aus der Hirnanhangsdrüse und macht den Schleim im Gebärmutterhals für Spermien schwer durchlässig. Zusätzlich wirkt es antimineralokortikoid (fördert die Ausscheidung von Natrium und Wasser und hält Kalium zurück) und antiandrogen.","nebenwirkungen":{"haeufig":["Zwischenblutungen, unregelmässige oder ausbleibende Blutungen","Regelschmerzen","Akne","Kopfschmerzen","Brustschmerzen","Übelkeit, Bauchschmerzen","Libidoabnahme, Stimmungsschwankungen","Gewichtszunahme"],"unbekannt":["Hyperkaliämie (erhöhtes Kalium)","Eierstockzysten","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nicht anwenden. Tritt unter der Einnahme eine Schwangerschaft ein, absetzen; Hinweise auf Fehlbildungen nach versehentlicher Einnahme gibt es nicht.","stillzeit":"Als reines Gestagenpräparat nach ärztlicher Beratung möglich (geringe Mengen in der Muttermilch, keine Beeinträchtigung der Milchbildung). Kombinationen mit Östrogen in der Stillzeit nicht empfohlen.","hinweise":["Täglich zur gleichen Zeit einnehmen (24 Hormon- und 4 wirkstofffreie Tabletten ohne Pause).","Bei vergessener Einnahme, Erbrechen oder starkem Durchfall Packungsbeilage beachten – gegebenenfalls zusätzlich Kondome verwenden.","Unregelmässige Blutungen sind besonders in den ersten Monaten häufig; anhaltende oder starke Blutungen ärztlich abklären lassen.","Bei eingeschränkter Nierenfunktion und gleichzeitiger Einnahme kaliumerhöhender Mittel Kalium kontrollieren lassen."],"darreichung":["Filmtabletten"]},"dulaglutid":{"wirkmechanismus":"Wirkt wie das körpereigene Darmhormon GLP-1, das nach dem Essen ausgeschüttet wird. Dulaglutid besteht aus zwei GLP-1-ähnlichen Peptidketten, die an ein verändertes Antikörperstück (Fc-Teil von IgG4) gekoppelt sind; dadurch wird es nur langsam abgebaut und wirkt eine Woche lang. Es steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung, verlangsamt die Magenentleerung und verstärkt das Sättigungsgefühl. In einer grossen Studie senkte es bei Typ-2-Diabetes das Risiko schwerer Herz-Kreislauf-Ereignisse.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen","Bauchschmerzen","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoff"],"haeufig":["Appetitminderung","Verdauungsbeschwerden, Verstopfung, Blähungen, Völlegefühl, Reflux, Aufstossen","Müdigkeit (Fatigue)","Sinustachykardie (erhöhter Puls)","AV-Block 1. Grades (leichte Verzögerung der Erregungsleitung im Herzen, im EKG sichtbar)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Dehydratation (Flüssigkeitsmangel)","Gallensteine (Cholelithiasis) und Cholezystitis (Gallenblasenentzündung)","Reaktionen an der Injektionsstelle"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["Nicht-mechanischer Darmverschluss (Ileus)"]},"schwangerschaft":"Nicht anwenden: Die Erfahrungen sind unzureichend, Tierversuche zeigten Fruchtschädigung. Bei Diabetes in der Schwangerschaft wird Insulin eingesetzt.","stillzeit":"Nicht anwenden, da nicht bekannt ist, ob Dulaglutid in die Muttermilch übergeht.","hinweise":["Einmal pro Woche am gleichen Wochentag spritzen, unabhängig vom Essen; der Wochentag kann gewechselt werden, wenn seit der letzten Dosis mindestens 3 Tage vergangen sind.","Vergessene Dosis nachholen, wenn bis zur nächsten planmässigen Dosis noch mindestens 3 Tage (72 Stunden) bleiben, sonst auslassen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen; bei Übelkeit, Erbrechen oder Durchfall ausreichend trinken.","Vor Operationen, Narkosen oder Magenspiegelungen die Behandlung angeben."],"darreichung":["Injektionslösung im Fertigpen (Einzeldosis)"]},"duloxetin":{"wirkmechanismus":"Hellt die Stimmung auf und dämpft die Schmerzweiterleitung, indem es die Botenstoffe Serotonin und Noradrenalin im Nervensystem länger wirken lässt. Duloxetin hemmt die Wiederaufnahme von Serotonin und Noradrenalin etwa gleich stark, Dopamin nur schwach. An histaminergen, dopaminergen, cholinergen und adrenergen Rezeptoren wirkt es kaum. Die schmerzlindernde Wirkung beruht auf der Verstärkung absteigender, schmerzhemmender Nervenbahnen im Rückenmark.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schläfrigkeit","Mundtrockenheit"],"haeufig":["Schwindel, Zittern, Kribbeln, Müdigkeit","Appetitminderung, Gewichtsabnahme","Schlaflosigkeit, Unruhe, Angst, abnorme Träume","Verminderte Libido, Orgasmus-, Erektions- und Ejakulationsstörungen","Verstopfung, Durchfall, Bauchschmerzen, Erbrechen, Dyspepsie (Verdauungsbeschwerden)","Herzklopfen, Blutdruckanstieg, Hitzewallungen","Vermehrtes Schwitzen, Hautausschlag","Verschwommenes Sehen, Ohrensausen, Muskelschmerzen und -krämpfe"],"gelegentlich":["Suizidgedanken","Herzrasen, Vorhofflimmern, Ohnmacht","Magen-Darm-Blutungen, Blutergüsse, Nasenbluten","Hepatitis, erhöhte Leberwerte, akute Leberschädigung","Erhöhter Blutzucker","Harnverhalt, erschwertes Wasserlassen","Lichtempfindlichkeit, Nesselsucht"],"selten":["Anaphylaxie, Angioödem","Hyponatriämie (Natriummangel), SIADH","Serotoninsyndrom, Krampfanfälle","Manie, Halluzinationen, Aggressivität, suizidales Verhalten","Leberversagen, Gelbsucht","Hypertensive Krise, Glaukom","Stevens-Johnson-Syndrom","Interstitielle Lungenerkrankung, eosinophile Pneumonie"],"sehrSelten":["Hautvaskulitis (Entzündung kleiner Hautgefässe)"],"unbekannt":["Stress-Kardiomyopathie (Takotsubo)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme bis zur Geburt sind beim Neugeborenen Anpassungsstörungen und Entzugssymptome sowie bei der Mutter ein erhöhtes Risiko für Nachblutungen möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen wird nicht empfohlen.","hinweise":["Kapseln unzerkaut schlucken, nicht öffnen (magensaftresistenter Inhalt).","Nicht abrupt absetzen, sondern über mindestens 2 Wochen ausschleichen (Absetzsymptome wie Schwindel, Kribbeln, Übelkeit).","Blutdruck und Puls regelmässig kontrollieren; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen ärztlich abklären lassen (Leber).","Viel Alkohol meiden (Leberschäden); die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Magensaftresistente Kapseln"]},"dupilumab":{"wirkmechanismus":"Hemmt gezielt eine bestimmte Art der allergischen Entzündung (Typ-2-Entzündung). Dupilumab ist ein menschlicher Antikörper, der an die Alpha-Untereinheit des Interleukin-4-Rezeptors bindet. Dadurch werden die Signale der Botenstoffe Interleukin-4 und Interleukin-13 blockiert, die Juckreiz, Ekzeme, Schleimbildung und Verengung der Atemwege fördern. Der Antikörper wird wie körpereigene Eiweisse abgebaut, nicht über die Leber-Enzyme.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Juckreiz, Schmerz)"],"haeufig":["Bindehautentzündung (Konjunktivitis), auch allergisch","Augenjucken, Lidrandentzündung (Blepharitis)","Lippenherpes","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Gelenkschmerzen"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Keratitis (Hornhautentzündung)","Trockenes Auge","Gesichtsrötung oder -ausschlag"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Serumkrankheit","Ulzerative Keratitis (Hornhautgeschwür)"]},"schwangerschaft":"Nur wenn der Nutzen das mögliche Risiko überwiegt; die Erfahrungen sind begrenzt, Tierversuche zeigen keine schädlichen Wirkungen.","stillzeit":"Unbekannt, ob Dupilumab in die Muttermilch übergeht; Entscheidung über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 1–4 Wochen unter die Haut gespritzt; nach Schulung auch selbst zu Hause möglich. Fertigspritze vor Gebrauch Raumtemperatur annehmen lassen.","Andere Asthma- oder Neurodermitis-Mittel nicht eigenmächtig absetzen.","Bei geröteten, juckenden oder schmerzenden Augen oder Sehstörungen ärztlich abklären lassen."],"darreichung":["Fertigspritze","Fertigpen"]},"durvalumab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, sodass körpereigene Abwehrzellen Krebszellen wieder erkennen und angreifen. Durvalumab ist ein humaner IgG1-Antikörper, der an den Liganden PD-L1 bindet und dessen Wechselwirkung mit den Rezeptoren PD-1 und CD80 auf T-Zellen blockiert. Viele Tumoren nutzen PD-L1, um T-Zellen abzuschalten; die Blockade reaktiviert die Immunantwort gegen den Tumor. Der Fc-Teil ist so verändert, dass er keine antikörperabhängige Zellzerstörung auslöst.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege","Husten","Durchfall","Bauchschmerzen","Hautausschlag, Juckreiz","Fieber","Hypothyreose (Schilddrüsenunterfunktion)"],"haeufig":["Lungenentzündung (Pneumonie), Grippe, Mundsoor","Pneumonitis (nicht-infektiöse Lungenentzündung)","Hyperthyreose (Schilddrüsenüberfunktion)","Erhöhte Leberwerte","Dysphonie (Heiserkeit)","Nächtliches Schwitzen, Muskelschmerzen","Erhöhtes Kreatinin, Schmerzen beim Wasserlösen","Periphere Ödeme, Infusionsreaktionen"],"gelegentlich":["Kolitis (Dickdarmentzündung)","Hepatitis (Leberentzündung)","Nebenniereninsuffizienz","Typ-1-Diabetes","Nephritis (Nierenentzündung)","Thyreoiditis (Schilddrüsenentzündung)","Interstitielle Lungenerkrankung"],"selten":["Hypophysitis (Entzündung der Hirnanhangsdrüse), Diabetes insipidus","Myokarditis (Herzmuskelentzündung)","Myositis, Myasthenia gravis"],"unbekannt":["Guillain-Barré-Syndrom","Enzephalitis (Hirnentzündung)","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht empfohlen: Die Blockade von PD-L1 kann die Toleranz gegenüber dem Ungeborenen stören, und IgG-Antikörper gehen über die Plazenta. Frauen im gebärfähigen Alter verhüten während der Behandlung und mindestens 3 Monate danach.","stillzeit":"Während der Behandlung und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue Beschwerden wie Durchfall, Bauchschmerzen, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch Monate nach Therapieende.","Den Patientenausweis immer bei sich tragen und allen Ärztinnen und Ärzten zeigen.","Schilddrüsen-, Leber- und Nierenwerte sowie Blutzucker werden regelmässig kontrolliert.","Kortison nicht eigenmächtig beginnen oder absetzen; immunvermittelte Nebenwirkungen werden oft mit Kortison behandelt."],"darreichung":["Infusionskonzentrat"]},"dutasterid":{"wirkmechanismus":"Lässt eine vergrösserte Prostata schrumpfen, indem es die Bildung des stark wirksamen Androgens Dihydrotestosteron (DHT) unterdrückt. Dutasterid hemmt beide Formen des Enzyms 5-Alpha-Reduktase (Typ 1 und Typ 2), die Testosteron in DHT umwandeln; der DHT-Spiegel im Blut sinkt um über 90 %. Das Prostatavolumen nimmt über Monate ab, die Beschwerden bessern sich meist nach 3–6 Monaten. Wegen der sehr langen Halbwertszeit von etwa 5 Wochen bleibt der Wirkstoff nach dem Absetzen noch monatelang im Körper.","nebenwirkungen":{"haeufig":["Erektionsstörung (Impotenz)","Verminderte Libido (Lust auf Sex)","Ejakulationsstörungen, z. B. vermindertes Spermavolumen","Brustbeschwerden (Spannungsgefühl, Vergrösserung)","Schwindel (in Kombination mit Tamsulosin)"],"gelegentlich":["Haarausfall (v. a. Körperbehaarung) oder vermehrter Haarwuchs","Herzinsuffizienz (v. a. in Kombination mit Tamsulosin)"],"unbekannt":["Überempfindlichkeitsreaktionen mit Ausschlag, Juckreiz, Nesselsucht, Angioödem","Depressive Verstimmung","Hodenschmerzen und Hodenschwellung","Brustkrebs beim Mann"]},"schwangerschaft":"Kontraindiziert. Der Wirkstoff wird über die Haut aufgenommen: Frauen, Kinder und Jugendliche sollen beschädigte, undichte Kapseln nicht berühren (sonst die Haut sofort mit Wasser und Seife waschen). Da Dutasterid ins Sperma übergeht, soll ein Kondom benutzt werden, wenn die Partnerin schwanger ist oder schwanger werden könnte.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Kapseln ganz schlucken, nicht kauen oder öffnen – der Inhalt reizt die Schleimhaut von Mund und Rachen.","Während der Behandlung und bis mindestens 6 Monate nach der letzten Einnahme kein Blut spenden.","Bei einer PSA-Bestimmung die Einnahme angeben.","Die Wirkung ist oft erst nach 3–6 Monaten spürbar; nicht vorzeitig absetzen."],"darreichung":["Weichkapseln"]},"dutasterid-tamsulosin":{"wirkmechanismus":"Erleichtert das Wasserlösen auf zwei Wegen. Tamsulosin blockiert Alpha-1A-Rezeptoren in Prostata und Blasenhals und entspannt die glatte Muskulatur – das wirkt innert Tagen. Dutasterid hemmt beide Formen der 5-Alpha-Reduktase und damit die Umwandlung von Testosteron in Dihydrotestosteron; die Prostata schrumpft über Monate. Beide Wirkstoffe werden über CYP3A4 abgebaut, Tamsulosin zusätzlich über CYP2D6.","nebenwirkungen":{"haeufig":["Erektionsstörungen","Verminderte Libido","Ejakulationsstörungen (z. B. vermindertes Ejakulatvolumen)","Brustvergrösserung oder -spannen beim Mann","Schwindel"],"gelegentlich":["Herzinsuffizienz","Kopfschmerzen, Herzklopfen","Blutdruckabfall beim Aufstehen","Schnupfen","Verstopfung, Durchfall, Übelkeit, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Schwächegefühl"],"selten":["Ohnmacht (Synkope)","Angioödem (Schwellung von Haut und Schleimhäuten)"],"sehrSelten":["Priapismus (schmerzhafte Dauererektion)","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Augenoperationen","Depression","Hodenschmerzen und -schwellung","Sehstörungen, Nasenbluten, Mundtrockenheit","Erythema multiforme, Hautablösung"]},"schwangerschaft":"Nur für Männer. Schwangere und Frauen, die schwanger werden könnten, dürfen undichte Kapseln nicht berühren (Dutasterid wird über die Haut aufgenommen und kann männliche Föten schädigen).","stillzeit":"Nicht anwendbar (nur für Männer).","hinweise":["Kapsel ganz schlucken, nicht öffnen oder kauen; täglich 30 Minuten nach derselben Mahlzeit einnehmen.","Die volle Wirkung auf die Prostata zeigt sich erst nach 3–6 Monaten.","Vor einer Augenoperation (grauer Star) die Einnahme angeben.","Während der Behandlung und bis 6 Monate danach kein Blut spenden; Kondom verwenden, wenn die Partnerin schwanger ist oder werden könnte."],"darreichung":["Hartkapseln"]},"dydrogesteron":{"wirkmechanismus":"Wirkt wie das körpereigene Gelbkörperhormon und bringt die Gebärmutterschleimhaut in die zweite Zyklusphase. Dydrogesteron ist ein oral wirksames Retroprogesteron, das sehr selektiv an Progesteronrezeptoren bindet und die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut umwandelt. Es hat keine östrogene, androgene oder kortisonartige Wirkung und hemmt in üblicher Dosis den Eisprung nicht. Sein Hauptabbauprodukt (20-alpha-Dihydrodydrogesteron) ist ebenfalls gestagen wirksam.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Übelkeit","Menstruationsstörungen (Zwischenblutungen, starke, schmerzhafte oder ausbleibende Blutungen)","Brustschmerzen oder Brustspannen"],"gelegentlich":["Depressive Verstimmung","Schwindel","Erbrechen","Leberfunktionsstörungen, teils mit Gelbsucht, Schwäche und Bauchschmerzen","Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Gewichtszunahme"],"selten":["Hämolytische Anämie (Blutarmut durch Zerfall roter Blutkörperchen)","Überempfindlichkeitsreaktionen","Schläfrigkeit","Angioödem (Schwellung von Gesicht und Rachen)","Wassereinlagerungen (Ödeme)","Brustschwellung","Grössenzunahme gestagenabhängiger Tumoren (z. B. Meningeom)"]},"schwangerschaft":"Je nach Präparat bei drohender Fehlgeburt infolge nachgewiesenen Progesteronmangels zugelassen und nur auf ärztliche Verordnung anzuwenden; ein schädigender Einfluss auf das Kind ist nicht belegt. Kombinationen mit Östrogen (Femoston) sind in der Schwangerschaft nicht angezeigt.","stillzeit":"Nicht anwenden – es ist nicht bekannt, ob Dydrogesteron in die Muttermilch übergeht.","hinweise":["Tabletten unabhängig von den Mahlzeiten mit etwas Flüssigkeit einnehmen; den vorgegebenen Zyklustagen genau folgen.","Dydrogesteron hemmt den Eisprung nicht und schützt nicht vor einer Schwangerschaft.","Bei Hormonersatz Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen; ungewöhnliche Blutungen abklären lassen."],"darreichung":["Filmtabletten"]}});
